
local function getOrCreateFolder(parent, name)
    local f = parent:FindFirstChild(name)
    if not f then
        f = Instance.new("Folder")
        f.Name = name
        f.Parent = parent
    end
    return f
end

local function setScript(parent, name, className, source)
    local s = parent:FindFirstChild(name)
    if not s or s.ClassName ~= className then
        if s then s:Destroy() end
        s = Instance.new(className)
        s.Name = name
        s.Parent = parent
    end
    s.Source = source
    return s
end

setScript(getOrCreateFolder(game:GetService("ReplicatedStorage"), "PanicShiftShared"), "Config", "ModuleScript", "--!strict\n--[[\n    PANIC SHIFT: Config.lua\n    Authoritative single source of truth for round timers, quotas,\n    task rewards, disaster weighting, cosmetic catalog, and player progression.\n]]\n\nlocal Config = {}\n\n-- Round Timers (in seconds)\nConfig.RoundTimers = {\n    LOBBY_DURATION = 20,          -- Countdown once min players are met\n    PREPARATION_DURATION = 30,    -- Pre-shift setup and orientation\n    MAIN_SHIFT_DURATION = 180,    -- 3 minutes of standard shift gameplay\n    CLOSING_RUSH_DURATION = 45,   -- 45 seconds of frantic quota scramble\n    RESULTS_DURATION = 15,        -- Paycheck and MVP celebration\n    RESET_DURATION = 5,           -- Level teardown and reset\n}\n\n-- Minimum and Maximum Players\nConfig.ServerConfig = {\n    MIN_PLAYERS_TO_START = 1,     -- Set to 1 for solo testing, tuned to 2+ for production\n    MAX_PLAYERS_PER_SERVER = 12,\n}\n\n-- Quota Scaling Configuration\n-- Quota = BaseQuota + (PlayerCount * QuotaPerPlayer)\nConfig.QuotaConfig = {\n    BASE_QUOTA = 15,\n    QUOTA_PER_PLAYER = 10,\n    CLOSING_RUSH_MULTIPLIER = 2.0, -- Points awarded count double during closing rush\n}\n\n-- Task Rewards & Duration Configuration\nConfig.Tasks = {\n    RESTOCK = {\n        Id = \"RESTOCK\",\n        Name = \"Restock Shelves\",\n        CreditReward = 10,\n        XpReward = 15,\n        QuotaPoints = 1,\n        InteractionDuration = 1.2, -- Time to hold interaction key\n        MaxSimultaneous = 6,\n    },\n    CLEAN_SPILL = {\n        Id = \"CLEAN_SPILL\",\n        Name = \"Clean Spill\",\n        CreditReward = 12,\n        XpReward = 18,\n        QuotaPoints = 1,\n        InteractionDuration = 2.0,\n        MaxSimultaneous = 5,\n    },\n    DELIVER_ORDER = {\n        Id = \"DELIVER_ORDER\",\n        Name = \"Deliver Order\",\n        CreditReward = 20,\n        XpReward = 25,\n        QuotaPoints = 2,\n        OrderTimeLimit = 60, -- Seconds to deliver before order expires\n        MaxSimultaneous = 3,\n    },\n    REPAIR = {\n        Id = \"REPAIR\",\n        Name = \"Repair Equipment\",\n        CreditReward = 25,\n        XpReward = 30,\n        QuotaPoints = 2,\n        InteractionDuration = 3.0,\n        MaxSimultaneous = 4,\n    },\n}\n\n-- Disaster Director Configuration\nConfig.Disasters = {\n    IntervalMin = 30, -- Seconds between disasters (minimum)\n    IntervalMax = 45, -- Seconds between disasters (maximum)\n    TelegraphDuration = 4.0, -- Warning alert duration before disaster mechanics activate\n    \n    Weights = {\n        RunawayCarts = 100,\n        Blackout = 90,\n        AngryCustomer = 85,\n        ProductAvalanche = 95,\n        SoapApocalypse = 90,\n        ManagerMadness = 80,\n    },\n    \n    Durations = {\n        RunawayCarts = 25,\n        Blackout = 30,\n        AngryCustomer = 35,\n        ProductAvalanche = 20,\n        SoapApocalypse = 25,\n        ManagerMadness = 30,\n    },\n}\n\n-- Cosmetic Items Catalog\nConfig.Cosmetics = {\n    -- Headwear\n    paper_bag_hat = {\n        Id = \"paper_bag_hat\",\n        Name = \"Paper Bag Hat\",\n        Type = \"Headwear\",\n        Price = 150,\n        Description = \"Recycled fashion at its finest.\",\n        AssetId = \"rbxassetid://0\",\n    },\n    traffic_cone_hat = {\n        Id = \"traffic_cone_hat\",\n        Name = \"Traffic Cone Hat\",\n        Type = \"Headwear\",\n        Price = 1200,\n        Description = \"Safety first, dignity second.\",\n        AssetId = \"rbxassetid://0\",\n    },\n    cereal_box_helmet = {\n        Id = \"cereal_box_helmet\",\n        Name = \"Cereal Box Helmet\",\n        Type = \"Headwear\",\n        Price = 600,\n        Description = \"Part of a balanced disaster survival kit.\",\n        AssetId = \"rbxassetid://0\",\n    },\n    manager_visor = {\n        Id = \"manager_visor\",\n        Name = \"Manager Visor\",\n        Type = \"Headwear\",\n        Price = 800,\n        Description = \"Conveys aggressive administrative authority.\",\n        AssetId = \"rbxassetid://0\",\n    },\n    \n    -- Uniforms\n    default_uniform = {\n        Id = \"default_uniform\",\n        Name = \"Classic Blue Apron\",\n        Type = \"Uniform\",\n        Price = 0,\n        Description = \"Standard issue company uniform.\",\n        AssetId = \"rbxassetid://0\",\n    },\n    golden_apron = {\n        Id = \"golden_apron\",\n        Name = \"Golden Apron\",\n        Type = \"Uniform\",\n        Price = 750,\n        Description = \"Shines brightly amidst the chaos.\",\n        AssetId = \"rbxassetid://0\",\n    },\n    hazmat_suit = {\n        Id = \"hazmat_suit\",\n        Name = \"Hazmat Suit\",\n        Type = \"Uniform\",\n        Price = 1800,\n        Description = \"For when Aisle 4 is completely compromised.\",\n        AssetId = \"rbxassetid://0\",\n    },\n    manager_suit = {\n        Id = \"manager_suit\",\n        Name = \"Manager Tuxedo\",\n        Type = \"Uniform\",\n        Price = 2500,\n        Description = \"Dress for the job you will lose in 3 minutes.\",\n        AssetId = \"rbxassetid://0\",\n    },\n}\n\n-- Daily Challenges Template\nConfig.DailyChallenges = {\n    {\n        Id = \"DAILY_TASKS_10\",\n        Description = \"Complete 10 supermarket tasks\",\n        TargetCount = 10,\n        CreditReward = 100,\n        XpReward = 150,\n    },\n    {\n        Id = \"DAILY_SURVIVE_DISASTER_3\",\n        Description = \"Survive 3 disaster events\",\n        TargetCount = 3,\n        CreditReward = 120,\n        XpReward = 180,\n    },\n    {\n        Id = \"DAILY_CLEAN_SPILLS_5\",\n        Description = \"Mop 5 messy spills\",\n        TargetCount = 5,\n        CreditReward = 90,\n        XpReward = 120,\n    },\n}\n\n-- Progression / XP Calculation\n-- Required XP for next level = BaseXP * (CurrentLevel ^ LevelExponent)\nConfig.Progression = {\n    BASE_XP = 100,\n    LEVEL_EXPONENT = 1.5,\n    \n    CalculateRequiredXp = function(level: number): number\n        return math.floor(Config.Progression.BASE_XP * (level ^ Config.Progression.LEVEL_EXPONENT))\n    end,\n}\n\n-- Rate Limiting Configuration (Anti-Exploit)\nConfig.RateLimits = {\n    TASK_ACTION_MAX_PER_SECOND = 4,\n    PURCHASE_MAX_PER_SECOND = 2,\n    EQUIP_MAX_PER_SECOND = 3,\n}\n\nreturn table.freeze(Config)\n")
setScript(getOrCreateFolder(game:GetService("ReplicatedStorage"), "PanicShiftShared"), "Constants", "ModuleScript", "--!strict\n--[[\n    PANIC SHIFT: Constants.lua\n    Central definitions for round states, task types, disaster keys,\n    network identifiers, and error codes.\n]]\n\nlocal Constants = {}\n\n-- Round State Machine States\nConstants.RoundStates = {\n    LOBBY = \"LOBBY\",\n    PREPARATION = \"PREPARATION\",\n    ACTIVE = \"ACTIVE\",\n    CLOSING = \"CLOSING\",\n    RESULTS = \"RESULTS\",\n    RESET = \"RESET\",\n}\n\n-- Core Task Types\nConstants.TaskTypes = {\n    RESTOCK = \"RESTOCK\",\n    CLEAN_SPILL = \"CLEAN_SPILL\",\n    DELIVER_ORDER = \"DELIVER_ORDER\",\n    REPAIR = \"REPAIR\",\n}\n\n-- Disaster Identifiers\nConstants.Disasters = {\n    RUNAWAY_CARTS = \"RunawayCarts\",\n    BLACKOUT = \"Blackout\",\n    ANGRY_CUSTOMER = \"AngryCustomer\",\n    PRODUCT_AVALANCHE = \"ProductAvalanche\",\n    SOAP_APOCALYPSE = \"SoapApocalypse\",\n    MANAGER_MADNESS = \"ManagerMadness\",\n}\n\n-- Remote Identifiers\nConstants.Remotes = {\n    -- RemoteFunctions (Client -> Server with response)\n    REQUEST_TASK_ACTION = \"RequestTaskAction\",\n    REQUEST_EQUIP_COSMETIC = \"RequestEquipCosmetic\",\n    REQUEST_PURCHASE_COSMETIC = \"RequestPurchaseCosmetic\",\n    \n    -- RemoteEvents (Server -> Client broadcast or targeted)\n    ROUND_STATE_CHANGED = \"RoundStateChanged\",\n    TASK_STATE_CHANGED = \"TaskStateChanged\",\n    DISASTER_STATE_CHANGED = \"DisasterStateChanged\",\n    PLAYER_PROFILE_UPDATED = \"PlayerProfileUpdated\",\n    ROUND_RESULTS = \"RoundResults\",\n}\n\n-- Disaster Lifecycle States\nConstants.DisasterStatus = {\n    TELEGRAPH = \"TELEGRAPH\",\n    ACTIVE = \"ACTIVE\",\n    COMPLETED = \"COMPLETED\",\n    CANCELLED = \"CANCELLED\",\n}\n\n-- Security & Validation Error Codes\nConstants.ErrorCodes = {\n    SUCCESS = \"SUCCESS\",\n    RATE_LIMITED = \"RATE_LIMITED\",\n    OUT_OF_RANGE = \"OUT_OF_RANGE\",\n    TASK_NOT_FOUND = \"TASK_NOT_FOUND\",\n    TASK_ALREADY_COMPLETED = \"TASK_ALREADY_COMPLETED\",\n    INVALID_STATE = \"INVALID_STATE\",\n    ITEM_NOT_OWNED = \"ITEM_NOT_OWNED\",\n    INSUFFICIENT_FUNDS = \"INSUFFICIENT_FUNDS\",\n    INVALID_ARGUMENTS = \"INVALID_ARGUMENTS\",\n    PROFILE_NOT_LOADED = \"PROFILE_NOT_LOADED\",\n}\n\n-- Collision & Interaction Groups\nConstants.CollisionGroups = {\n    PLAYERS = \"PanicShiftPlayers\",\n    CARTS = \"PanicShiftCarts\",\n    DEBRIS = \"PanicShiftDebris\",\n    BOUNDARIES = \"PanicShiftBoundaries\",\n}\n\n-- Max interaction distance in studs\nConstants.MAX_INTERACTION_DISTANCE = 14\n\nreturn table.freeze(Constants)\n")
setScript(getOrCreateFolder(game:GetService("ReplicatedStorage"), "PanicShiftShared"), "Network", "ModuleScript", "--!strict\n--[[\n    PANIC SHIFT: Network.lua\n    Centralized network manager for remote creation, retrieval, and registration.\n    Prevents race conditions between server startup and client replication.\n]]\n\nlocal ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal RunService = game:GetService(\"RunService\")\n\nlocal Constants = require(script.Parent.Constants)\n\nlocal Network = {}\n\nlocal REMOTES_FOLDER_NAME = \"PanicShiftRemotes\"\nlocal remotesFolder: Folder\n\n-- Retrieves or creates the Remotes container folder\nlocal function getRemotesFolder(): Folder\n    if remotesFolder then\n        return remotesFolder\n    end\n\n    if RunService:IsServer() then\n        local existing = ReplicatedStorage:FindFirstChild(REMOTES_FOLDER_NAME)\n        if existing and existing:IsA(\"Folder\") then\n            remotesFolder = existing\n        else\n            local folder = Instance.new(\"Folder\")\n            folder.Name = REMOTES_FOLDER_NAME\n            folder.Parent = ReplicatedStorage\n            remotesFolder = folder\n        end\n    else\n        remotesFolder = ReplicatedStorage:WaitForChild(REMOTES_FOLDER_NAME, 10) :: Folder\n        if not remotesFolder then\n            error(string.format(\"[PanicShift Network] Timed out waiting for %s folder on client!\", REMOTES_FOLDER_NAME))\n        end\n    end\n\n    return remotesFolder\nend\n\n-- Initializes all required remotes on the server\nfunction Network.InitServer(): ()\n    assert(RunService:IsServer(), \"[PanicShift Network] InitServer must only be called on the server!\")\n    local folder = getRemotesFolder()\n\n    -- RemoteFunctions\n    local functions = {\n        Constants.Remotes.REQUEST_TASK_ACTION,\n        Constants.Remotes.REQUEST_EQUIP_COSMETIC,\n        Constants.Remotes.REQUEST_PURCHASE_COSMETIC,\n    }\n    for _, name in ipairs(functions) do\n        if not folder:FindFirstChild(name) then\n            local remoteFunc = Instance.new(\"RemoteFunction\")\n            remoteFunc.Name = name\n            remoteFunc.Parent = folder\n        end\n    end\n\n    -- RemoteEvents\n    local events = {\n        Constants.Remotes.ROUND_STATE_CHANGED,\n        Constants.Remotes.TASK_STATE_CHANGED,\n        Constants.Remotes.DISASTER_STATE_CHANGED,\n        Constants.Remotes.PLAYER_PROFILE_UPDATED,\n        Constants.Remotes.ROUND_RESULTS,\n    }\n    for _, name in ipairs(events) do\n        if not folder:FindFirstChild(name) then\n            local remoteEvt = Instance.new(\"RemoteEvent\")\n            remoteEvt.Name = name\n            remoteEvt.Parent = folder\n        end\n    end\nend\n\n-- Retrieves a RemoteEvent by name\nfunction Network.GetRemoteEvent(name: string): RemoteEvent\n    local folder = getRemotesFolder()\n    local remote = folder:WaitForChild(name, 10) :: RemoteEvent\n    if not remote or not remote:IsA(\"RemoteEvent\") then\n        error(string.format(\"[PanicShift Network] RemoteEvent '%s' was not found in %s!\", name, REMOTES_FOLDER_NAME))\n    end\n    return remote\nend\n\n-- Retrieves a RemoteFunction by name\nfunction Network.GetRemoteFunction(name: string): RemoteFunction\n    local folder = getRemotesFolder()\n    local remote = folder:WaitForChild(name, 10) :: RemoteFunction\n    if not remote or not remote:IsA(\"RemoteFunction\") then\n        error(string.format(\"[PanicShift Network] RemoteFunction '%s' was not found in %s!\", name, REMOTES_FOLDER_NAME))\n    end\n    return remote\nend\n\nreturn table.freeze(Network)\n")
setScript(getOrCreateFolder(game:GetService("ReplicatedStorage"), "PanicShiftShared"), "Types", "ModuleScript", "--!strict\n--[[\n    PANIC SHIFT: Types.lua\n    Exported Luau types for strict compile-time checking across services,\n    controllers, networks, and data stores.\n]]\n\nexport type RoundState = \"LOBBY\" | \"PREPARATION\" | \"ACTIVE\" | \"CLOSING\" | \"RESULTS\" | \"RESET\"\n\nexport type TaskType = \"RESTOCK\" | \"CLEAN_SPILL\" | \"DELIVER_ORDER\" | \"REPAIR\"\n\nexport type TaskData = {\n    Id: string,\n    Type: TaskType,\n    Title: string,\n    LocationPart: BasePart?,\n    Position: Vector3,\n    IsActive: boolean,\n    IsCompleted: boolean,\n    AssignedPlayer: Player?,\n    CreatedAt: number,\n    ExpiresAt: number?,\n    Metadata: { [string]: any }?,\n}\n\nexport type DisasterContext = {\n    RoundId: string,\n    Duration: number,\n    SupermarketMap: Model?,\n    Services: { [string]: any },\n    TelegraphDuration: number,\n}\n\nexport type LifetimeStats = {\n    shiftsCompleted: number,\n    shiftsWon: number,\n    tasksCompleted: number,\n    disastersSurvives: number,\n    spillsCleaned: number,\n    ordersDelivered: number,\n}\n\nexport type DailyChallengeProgress = {\n    resetKey: string,\n    completed: { [string]: boolean },\n    progress: { [string]: number },\n}\n\nexport type UserSettings = {\n    musicVolume: number,\n    sfxVolume: number,\n    screenShake: boolean,\n}\n\nexport type PlayerProfile = {\n    schemaVersion: number,\n    credits: number,\n    xp: number,\n    level: number,\n    ownedCosmetics: { string },\n    equippedCosmetic: string,\n    equippedHat: string?,\n    lifetimeStats: LifetimeStats,\n    dailyChallenges: DailyChallengeProgress,\n    settings: UserSettings,\n}\n\nexport type NetworkResponse = {\n    Success: boolean,\n    ErrorCode: string,\n    Message: string?,\n    Data: any?,\n}\n\nexport type RoundResultsData = {\n    Success: boolean,\n    ShiftName: string,\n    QuotaReached: number,\n    QuotaTarget: number,\n    DurationSeconds: number,\n    TeamBonusCredits: number,\n    IndividualStats: {\n        [number]: {\n            PlayerName: string,\n            TasksCompleted: number,\n            CreditsEarned: number,\n            XpEarned: number,\n            IsMvp: boolean,\n        }\n    },\n}\n\nexport type Service = {\n    Name: string,\n    Init: (self: any, services: { [string]: any }) -> (),\n    Start: (self: any) -> (),\n    [string]: any,\n}\n\nexport type Controller = {\n    Name: string,\n    Init: (self: any, controllers: { [string]: any }) -> (),\n    Start: (self: any) -> (),\n    [string]: any,\n}\n\nreturn {}\n")
setScript(getOrCreateFolder(game:GetService("ReplicatedStorage"), "PanicShiftShared"), "Utility", "ModuleScript", "--!strict\n--[[\n    PANIC SHIFT: Utility.lua\n    Shared utility functions for math, distance checks, table operations,\n    exponential backoff retries, rate limiting, and network payloads.\n]]\n\nlocal Types = require(script.Parent.Types)\n\nlocal Utility = {}\n\n-- Checks if two 3D positions are within a maximum Euclidean distance\nfunction Utility.IsWithinDistance(posA: Vector3, posB: Vector3, maxDistance: number): boolean\n    local diff = posA - posB\n    return diff:Dot(diff) <= (maxDistance * maxDistance)\nend\n\n-- Extracts the PrimaryPart or HumanoidRootPart position safely from a character model\nfunction Utility.GetCharacterPosition(character: Model?): Vector3?\n    if not character then\n        return nil\n    end\n    local root = character:FindFirstChild(\"HumanoidRootPart\")\n    if root and root:IsA(\"BasePart\") then\n        return root.Position\n    end\n    if character.PrimaryPart then\n        return character.PrimaryPart.Position\n    end\n    return nil\nend\n\n-- Deep copies any Lua table recursively\nfunction Utility.DeepCopy<T>(original: T): T\n    if typeof(original) ~= \"table\" then\n        return original\n    end\n    local copy = {}\n    for key, value in pairs(original :: any) do\n        if typeof(value) == \"table\" then\n            copy[key] = Utility.DeepCopy(value)\n        else\n            copy[key] = value\n        end\n    end\n    return copy :: any\nend\n\n-- Formats seconds into a clean \"MM:SS\" time string\nfunction Utility.FormatTime(totalSeconds: number): string\n    local safeSeconds = math.max(0, math.floor(totalSeconds))\n    local minutes = math.floor(safeSeconds / 60)\n    local seconds = safeSeconds % 60\n    return string.format(\"%02d:%02d\", minutes, seconds)\nend\n\n-- Generates a lightweight unique identifier\nlocal seedCounter = 0\nfunction Utility.GenerateUUID(): string\n    seedCounter = (seedCounter + 1) % 1000000\n    local timestamp = os.time()\n    local randomPart = math.random(10000, 99999)\n    return string.format(\"PS-%d-%d-%06d\", timestamp, randomPart, seedCounter)\nend\n\n-- Creates a standard token-bucket rate limiter per key (e.g., UserId)\nfunction Utility.CreateRateLimiter(maxCalls: number, windowSeconds: number)\n    local records: { [any]: { count: number, resetTime: number } } = {}\n\n    return function(key: any): boolean\n        local now = os.clock()\n        local record = records[key]\n\n        if not record or now >= record.resetTime then\n            records[key] = {\n                count = 1,\n                resetTime = now + windowSeconds,\n            }\n            return true\n        end\n\n        if record.count < maxCalls then\n            record.count = record.count + 1\n            return true\n        end\n\n        return false -- Rate limit exceeded\n    end\nend\n\n-- Executes a fallible operation with bounded retries and exponential backoff\nfunction Utility.RetryWithBackoff<T>(\n    maxAttempts: number,\n    initialDelay: number,\n    operation: () -> (boolean, T)\n): (boolean, T?)\n    local currentDelay = initialDelay\n    for attempt = 1, maxAttempts do\n        local success, result = operation()\n        if success then\n            return true, result\n        end\n        if attempt < maxAttempts then\n            task.wait(currentDelay)\n            currentDelay = currentDelay * 2\n        end\n    end\n    return false, nil\nend\n\n-- Creates a standard success response payload\nfunction Utility.CreateSuccessResponse(data: any?): Types.NetworkResponse\n    return {\n        Success = true,\n        ErrorCode = \"SUCCESS\",\n        Message = nil,\n        Data = data,\n    }\nend\n\n-- Creates a standard error response payload\nfunction Utility.CreateErrorResponse(errorCode: string, message: string?): Types.NetworkResponse\n    return {\n        Success = false,\n        ErrorCode = errorCode,\n        Message = message,\n        Data = nil,\n    }\nend\n\nreturn table.freeze(Utility)\n")
setScript(getOrCreateFolder(game:GetService("ServerStorage"), "DisasterModules"), "AngryCustomer", "ModuleScript", "--!strict\n--[[\n    PANIC SHIFT: Disaster - AngryCustomer.lua\n    Disaster 3: An oversized cartoon customer aggressively stalks employees\n    demanding to speak to the manager. Employees must avoid being cornered.\n]]\n\nlocal Workspace = game:GetService(\"Workspace\")\nlocal Players = game:GetService(\"Players\")\n\nlocal Shared = game:GetService(\"ReplicatedStorage\"):WaitForChild(\"PanicShiftShared\")\nlocal Types = require(Shared:WaitForChild(\"Types\"))\nlocal Utility = require(Shared:WaitForChild(\"Utility\"))\n\nlocal AngryCustomer = {\n    Name = \"AngryCustomer\",\n}\n\nlocal customerNpc: Model? = nil\nlocal aiThread: thread? = nil\n\n-- Creates the oversized cartoon customer model\nlocal function createCustomerNpc(spawnPos: Vector3): Model\n    local model = Instance.new(\"Model\")\n    model.Name = \"AngryCustomerNPC\"\n    model.Parent = Workspace\n\n    -- Humanoid Root\n    local root = Instance.new(\"Part\")\n    root.Name = \"HumanoidRootPart\"\n    root.Size = Vector3.new(3, 4, 2)\n    root.CFrame = CFrame.new(spawnPos)\n    root.Transparency = 1\n    root.CanCollide = false\n    root.Anchored = false\n    root.Parent = model\n    model.PrimaryPart = root\n\n    -- Torso (Purple flowery dress)\n    local torso = Instance.new(\"Part\")\n    torso.Name = \"Torso\"\n    torso.Size = Vector3.new(4, 5, 2.5)\n    torso.CFrame = CFrame.new(spawnPos)\n    torso.Color = Color3.fromRGB(180, 50, 160)\n    torso.Material = Enum.Material.Fabric\n    torso.CanCollide = true\n    torso.Anchored = false\n    torso.Parent = model\n\n    local torsoWeld = Instance.new(\"WeldConstraint\")\n    torsoWeld.Part0 = root\n    torsoWeld.Part1 = torso\n    torsoWeld.Parent = root\n\n    -- Head & Sunglasses\n    local head = Instance.new(\"Part\")\n    head.Name = \"Head\"\n    head.Size = Vector3.new(2.5, 2.5, 2.5)\n    head.CFrame = CFrame.new(spawnPos + Vector3.new(0, 3.8, 0))\n    head.Color = Color3.fromRGB(255, 215, 175)\n    head.Material = Enum.Material.SmoothPlastic\n    head.CanCollide = false\n    head.Anchored = false\n    head.Parent = model\n\n    local headWeld = Instance.new(\"WeldConstraint\")\n    headWeld.Part0 = torso\n    headWeld.Part1 = head\n    headWeld.Parent = head\n\n    -- Coupon Book Weapon\n    local coupon = Instance.new(\"Part\")\n    coupon.Name = \"CouponBook\"\n    coupon.Size = Vector3.new(1.8, 2.2, 0.5)\n    coupon.CFrame = CFrame.new(spawnPos + Vector3.new(2.4, 0.5, -1))\n    coupon.Color = Color3.fromRGB(240, 230, 80)\n    coupon.Material = Enum.Material.SmoothPlastic\n    coupon.CanCollide = false\n    coupon.Anchored = false\n    coupon.Parent = model\n\n    local couponWeld = Instance.new(\"WeldConstraint\")\n    couponWeld.Part0 = torso\n    couponWeld.Part1 = coupon\n    couponWeld.Parent = coupon\n\n    -- Billboard Nameplate\n    local billboard = Instance.new(\"BillboardGui\")\n    billboard.Size = UDim2.new(0, 200, 0, 50)\n    billboard.StudsOffset = Vector3.new(0, 3.5, 0)\n    billboard.AlwaysOnTop = true\n    billboard.Parent = head\n\n    local label = Instance.new(\"TextLabel\")\n    label.Size = UDim2.new(1, 0, 1, 0)\n    label.BackgroundTransparency = 1\n    label.Text = \"🚨 DEMANDS TO SEE THE MANAGER!\"\n    label.TextColor3 = Color3.fromRGB(255, 40, 40)\n    label.Font = Enum.Font.FredokaOne\n    label.TextScaled = true\n    label.Parent = billboard\n\n    -- Humanoid Controller\n    local humanoid = Instance.new(\"Humanoid\")\n    humanoid.MaxHealth = 1000\n    humanoid.Health = 1000\n    humanoid.WalkSpeed = 20 -- Fast, aggressive pursuit\n    humanoid.Parent = model\n\n    -- Comedic tackle detection\n    local debounce = false\n    torso.Touched:Connect(function(otherPart: BasePart)\n        if debounce then return end\n        local char = otherPart.Parent\n        local h = char and char:FindFirstChildOfClass(\"Humanoid\")\n        if h and h ~= humanoid and not debounce then\n            debounce = true\n            local charRoot = char:FindFirstChild(\"HumanoidRootPart\") :: BasePart?\n            if charRoot then\n                charRoot.AssemblyLinearVelocity = (charRoot.Position - torso.Position).Unit * 30 + Vector3.new(0, 12, 0)\n                h.PlatformStand = true\n                task.delay(1.5, function()\n                    if h and h.Parent then\n                        h.PlatformStand = false\n                    end\n                end)\n            end\n            task.delay(2.0, function()\n                debounce = false\n            end)\n        end\n    end)\n\n    return model\nend\n\nfunction AngryCustomer.CanStart(context: Types.DisasterContext?): boolean\n    return true\nend\n\nfunction AngryCustomer.Start(context: Types.DisasterContext): ()\n    print(\"[Disaster: AngryCustomer] Customer entered demanding a manager!\")\n\n    customerNpc = createCustomerNpc(Vector3.new(0, 4, -30))\n\n    -- AI loop: repeatedly finds and paths towards nearest player\n    aiThread = task.spawn(function()\n        while customerNpc and customerNpc.Parent do\n            local humanoid = customerNpc:FindFirstChildOfClass(\"Humanoid\")\n            local root = customerNpc.PrimaryPart\n\n            if humanoid and root then\n                local nearestPlayer: Player? = nil\n                local shortestDist = 9999\n\n                for _, player in ipairs(Players:GetPlayers()) do\n                    local char = player.Character\n                    local charPos = Utility.GetCharacterPosition(char)\n                    if charPos then\n                        local dist = (charPos - root.Position).Magnitude\n                        if dist < shortestDist then\n                            shortestDist = dist\n                            nearestPlayer = player\n                        end\n                    end\n                end\n\n                if nearestPlayer and nearestPlayer.Character then\n                    local targetPos = Utility.GetCharacterPosition(nearestPlayer.Character)\n                    if targetPos then\n                        humanoid:MoveTo(targetPos)\n                    end\n                else\n                    -- Wander aisles\n                    humanoid:MoveTo(Vector3.new(math.random(-45, 45), 2, math.random(-10, 40)))\n                end\n            end\n            task.wait(0.8)\n        end\n    end)\nend\n\nfunction AngryCustomer.Stop(context: Types.DisasterContext?): ()\n    print(\"[Disaster: AngryCustomer] Customer stormed out.\")\n    if aiThread then\n        task.cancel(aiThread)\n        aiThread = nil\n    end\n\n    if customerNpc and customerNpc.Parent then\n        customerNpc:Destroy()\n        customerNpc = nil\n    end\nend\n\nreturn AngryCustomer\n")
setScript(getOrCreateFolder(game:GetService("ServerStorage"), "DisasterModules"), "Blackout", "ModuleScript", "--!strict\n--[[\n    PANIC SHIFT: Disaster - Blackout.lua\n    Disaster 2: Complete power outage with emergency red lights.\n    Players locate and flip BreakerPanel_1 and BreakerPanel_2 to restore power early.\n]]\n\nlocal Lighting = game:GetService(\"Lighting\")\nlocal Workspace = game:GetService(\"Workspace\")\nlocal Players = game:GetService(\"Players\")\n\nlocal Shared = game:GetService(\"ReplicatedStorage\"):WaitForChild(\"PanicShiftShared\")\nlocal Types = require(Shared:WaitForChild(\"Types\"))\n\nlocal Blackout = {\n    Name = \"Blackout\",\n}\n\nlocal originalBrightness: number = 2\nlocal originalAmbient: Color3 = Color3.fromRGB(128, 128, 128)\nlocal originalOutdoorAmbient: Color3 = Color3.fromRGB(128, 128, 128)\nlocal breakerPrompts: { ProximityPrompt } = {}\nlocal breakersFixed = 0\nlocal modifiedNeons: { { part: Part, originalColor: Color3 } } = {}\n\nfunction Blackout.CanStart(context: Types.DisasterContext?): boolean\n    return true\nend\n\nfunction Blackout.Start(context: Types.DisasterContext): ()\n    print(\"[Disaster: Blackout] Power outage triggered! Switching to emergency lighting.\")\n\n    originalBrightness = Lighting.Brightness\n    originalAmbient = Lighting.Ambient\n    originalOutdoorAmbient = Lighting.OutdoorAmbient\n\n    -- Deep retail darkness\n    Lighting.Brightness = 0.1\n    Lighting.Ambient = Color3.fromRGB(10, 10, 18)\n    Lighting.OutdoorAmbient = Color3.fromRGB(10, 10, 18)\n\n    local map = context.SupermarketMap or Workspace:FindFirstChild(\"SupermarketMap\")\n    if not map then return end\n\n    -- Turn ceiling lights into emergency pulsating red neon\n    local arch = map:FindFirstChild(\"Architecture\")\n    if arch then\n        for _, child in ipairs(arch:GetChildren()) do\n            if child.Name == \"LightFixture\" then\n                local tube = child:FindFirstChild(\"NeonTube\")\n                if tube and tube:IsA(\"Part\") then\n                    table.insert(modifiedNeons, { part = tube, originalColor = tube.Color })\n                    tube.Color = Color3.fromRGB(255, 30, 30)\n                    local light = tube:FindFirstChildOfClass(\"PointLight\")\n                    if light then\n                        light.Color = Color3.fromRGB(255, 40, 40)\n                        light.Brightness = 0.8\n                    end\n                end\n            end\n        end\n    end\n\n    -- Hook interactive ProximityPrompts onto the two breaker boxes\n    breakersFixed = 0\n    local maintenance = map:FindFirstChild(\"Maintenance\")\n    if maintenance then\n        for _, panelName in ipairs({ \"BreakerPanel_1\", \"BreakerPanel_2\" }) do\n            local panel = maintenance:FindFirstChild(panelName)\n            if panel and panel:IsA(\"BasePart\") then\n                local prompt = Instance.new(\"ProximityPrompt\")\n                prompt.ActionText = \"Restore Circuit\"\n                prompt.ObjectText = panelName\n                prompt.HoldDuration = 2.0\n                prompt.MaxActivationDistance = 9\n                prompt.RequiresLineOfSight = false\n                prompt.Parent = panel\n\n                prompt.Triggered:Connect(function(player: Player)\n                    prompt.Enabled = false\n                    breakersFixed = breakersFixed + 1\n                    print(string.format(\"[Blackout] %s flipped %s! (%d/2)\", player.Name, panelName, breakersFixed))\n\n                    if breakersFixed >= 2 then\n                        print(\"[Blackout] Both circuit breakers restored! Early power restoration.\")\n                        local disasterService = context.Services.DisasterService\n                        if disasterService then\n                            disasterService:StopActiveDisaster()\n                        end\n                    end\n                end)\n\n                table.insert(breakerPrompts, prompt)\n            end\n        end\n    end\nend\n\nfunction Blackout.Stop(context: Types.DisasterContext?): ()\n    print(\"[Disaster: Blackout] Power restored. Resetting lighting.\")\n\n    Lighting.Brightness = originalBrightness\n    Lighting.Ambient = originalAmbient\n    Lighting.OutdoorAmbient = originalOutdoorAmbient\n\n    -- Restore light tube colors\n    for _, item in ipairs(modifiedNeons) do\n        if item.part and item.part.Parent then\n            item.part.Color = item.originalColor\n            local light = item.part:FindFirstChildOfClass(\"PointLight\")\n            if light then\n                light.Color = item.originalColor\n                light.Brightness = 1.2\n            end\n        end\n    end\n    table.clear(modifiedNeons)\n\n    -- Clean up prompts\n    for _, prompt in ipairs(breakerPrompts) do\n        if prompt and prompt.Parent then\n            prompt:Destroy()\n        end\n    end\n    table.clear(breakerPrompts)\nend\n\nreturn Blackout\n")
setScript(getOrCreateFolder(game:GetService("ServerStorage"), "DisasterModules"), "ManagerMadness", "ModuleScript", "--!strict\n--[[\n    PANIC SHIFT: Disaster - ManagerMadness.lua\n    Disaster 6: Absurd corporate emergency store policies announced over PA.\n    Enforces funny temporary movement or task constraints.\n]]\n\nlocal Players = game:GetService(\"Players\")\n\nlocal Shared = game:GetService(\"ReplicatedStorage\"):WaitForChild(\"PanicShiftShared\")\nlocal Types = require(Shared:WaitForChild(\"Types\"))\n\nlocal ManagerMadness = {\n    Name = \"ManagerMadness\",\n}\n\nlocal POLICIES = {\n    {\n        Code = \"POLICY_WALK\",\n        Title = \"POLICY 402: NO SPRINTING!\",\n        Description = \"Walk with retail dignity! Speed capped at 10 studs/sec.\",\n        WalkSpeed = 10,\n        JumpPower = 50,\n    },\n    {\n        Code = \"POLICY_NO_JUMP\",\n        Title = \"POLICY 501: ZERO GRAVITY PROHIBITED!\",\n        Description = \"Associates must keep both feet on the floor at all times. No jumping!\",\n        WalkSpeed = 16,\n        JumpPower = 0,\n    },\n    {\n        Code = \"POLICY_DOUBLE_TIME\",\n        Title = \"POLICY 603: OVERTIME BLITZ!\",\n        Description = \"Corporate bonus approved: All task quota points count DOUBLE!\",\n        WalkSpeed = 18,\n        JumpPower = 55,\n    },\n}\n\nlocal activePolicyIndex = 1\n\nfunction ManagerMadness.CanStart(context: Types.DisasterContext?): boolean\n    return true\nend\n\nfunction ManagerMadness.Start(context: Types.DisasterContext): ()\n    activePolicyIndex = math.random(1, #POLICIES)\n    local policy = POLICIES[activePolicyIndex]\n\n    print(string.format(\"[Disaster: ManagerMadness] Announcement: '%s' - %s\", policy.Title, policy.Description))\n\n    -- Apply movement policy to all current player characters\n    for _, player in ipairs(Players:GetPlayers()) do\n        local character = player.Character\n        local humanoid = character and character:FindFirstChildOfClass(\"Humanoid\")\n        if humanoid then\n            humanoid.WalkSpeed = policy.WalkSpeed\n            humanoid.JumpPower = policy.JumpPower\n        end\n    end\nend\n\nfunction ManagerMadness.Stop(context: Types.DisasterContext?): ()\n    print(\"[Disaster: ManagerMadness] Shift policy rescinded. Standard operating procedures resumed.\")\n\n    -- Restore standard humanoid movement\n    for _, player in ipairs(Players:GetPlayers()) do\n        local character = player.Character\n        local humanoid = character and character:FindFirstChildOfClass(\"Humanoid\")\n        if humanoid then\n            humanoid.WalkSpeed = 16\n            humanoid.JumpPower = 50\n        end\n    end\n\n    -- Reward complying associates with 25 bonus credits\n    if context and context.Services and context.Services.EconomyService then\n        for _, player in ipairs(Players:GetPlayers()) do\n            context.Services.EconomyService:AwardCredits(player, 25, \"ManagerPolicyCompliance\")\n        end\n    end\nend\n\nreturn ManagerMadness\n")
setScript(getOrCreateFolder(game:GetService("ServerStorage"), "DisasterModules"), "ProductAvalanche", "ModuleScript", "--!strict\n--[[\n    PANIC SHIFT: Disaster - ProductAvalanche.lua\n    Disaster 4: Gondola shelf in Aisle 2 collapses, sending dozens of soup cans\n    and cereal boxes tumbling into the aisle with slapstick physics.\n]]\n\nlocal Workspace = game:GetService(\"Workspace\")\nlocal Players = game:GetService(\"Players\")\n\nlocal Shared = game:GetService(\"ReplicatedStorage\"):WaitForChild(\"PanicShiftShared\")\nlocal Types = require(Shared:WaitForChild(\"Types\"))\nlocal Utility = require(Shared:WaitForChild(\"Utility\"))\n\nlocal ProductAvalanche = {\n    Name = \"ProductAvalanche\",\n}\n\nlocal avalancheFolder: Folder? = nil\nlocal dangerDecals: { Instance } = {}\n\nfunction ProductAvalanche.CanStart(context: Types.DisasterContext?): boolean\n    local map = context and context.SupermarketMap or Workspace:FindFirstChild(\"SupermarketMap\")\n    return map ~= nil\nend\n\nfunction ProductAvalanche.Start(context: Types.DisasterContext): ()\n    print(\"[Disaster: ProductAvalanche] Creaking metal heard in Aisle 2!\")\n\n    local map = context.SupermarketMap or Workspace:FindFirstChild(\"SupermarketMap\")\n    if not map then return end\n\n    avalancheFolder = Instance.new(\"Folder\")\n    avalancheFolder.Name = \"ActiveAvalancheDebris\"\n    avalancheFolder.Parent = Workspace\n\n    -- 1. Floor danger warning strips along Aisle 2 (X = -15, Z from -10 to 40)\n    for z = -10, 40, 10 do\n        local warningPart = Instance.new(\"Part\")\n        warningPart.Name = \"DangerZone\"\n        warningPart.Size = Vector3.new(12, 0.1, 8)\n        warningPart.CFrame = CFrame.new(-15, 0.08, z)\n        warningPart.Color = Color3.fromRGB(255, 60, 60)\n        warningPart.Material = Enum.Material.Neon\n        warningPart.Transparency = 0.5\n        warningPart.Anchored = true\n        warningPart.CanCollide = false\n        warningPart.Parent = avalancheFolder\n        table.insert(dangerDecals, warningPart)\n    end\n\n    -- 2. Avalanche collapse: Spawn 30 unanchored bouncing soup cans and cracker boxes\n    task.delay(1.5, function()\n        if not avalancheFolder then return end\n\n        for i = 1, 30 do\n            local isCan = (i % 2 == 0)\n            local debris = Instance.new(\"Part\")\n            debris.Name = isCan and \"SoupCan\" or \"CerealBox\"\n            \n            if isCan then\n                debris.Shape = Enum.PartType.Cylinder\n                debris.Size = Vector3.new(2.2, 1.6, 1.6)\n                debris.Color = Color3.fromRGB(230, 45, 45) -- Tomato soup red\n            else\n                debris.Size = Vector3.new(2.2, 2.5, 1.2)\n                debris.Color = Color3.fromRGB(245, 175, 45) -- Cereal gold\n            end\n\n            debris.Material = Enum.Material.SmoothPlastic\n            debris.Anchored = false\n            debris.CanCollide = true\n            debris.CustomPhysicalProperties = PhysicalProperties.new(0.5, 0.4, 0.7) -- Very bouncy\n            \n            -- Spawn along Aisle 2 shelf height (Y = 10 to 14)\n            local dropZ = math.random(-10, 35)\n            debris.CFrame = CFrame.new(-15 + math.random(-2, 2), math.random(10, 15), dropZ) * CFrame.Angles(math.random(), math.random(), math.random())\n            debris.AssemblyLinearVelocity = Vector3.new(math.random(-15, 15), -10, math.random(-15, 15))\n            debris.Parent = avalancheFolder\n\n            -- Comedic hit detection\n            local debounce = false\n            debris.Touched:Connect(function(hit: BasePart)\n                if debounce then return end\n                local char = hit.Parent\n                local humanoid = char and char:FindFirstChildOfClass(\"Humanoid\")\n                if humanoid and not debounce then\n                    debounce = true\n                    humanoid.PlatformStand = true\n                    task.delay(1.2, function()\n                        if humanoid and humanoid.Parent then\n                            humanoid.PlatformStand = false\n                        end\n                    end)\n                end\n            end)\n        end\n    end)\nend\n\nfunction ProductAvalanche.Stop(context: Types.DisasterContext?): ()\n    print(\"[Disaster: ProductAvalanche] Maintenance cleared the fallen products.\")\n\n    if avalancheFolder then\n        avalancheFolder:Destroy()\n        avalancheFolder = nil\n    end\n\n    table.clear(dangerDecals)\nend\n\nreturn ProductAvalanche\n")
setScript(getOrCreateFolder(game:GetService("ServerStorage"), "DisasterModules"), "RunawayCarts", "ModuleScript", "--!strict\n--[[\n    PANIC SHIFT: Disaster - RunawayCarts.lua\n    Disaster 1: Rogue shopping carts move through aisles at high velocity.\n    Players must dodge collisions; returning carts into corrals grants bonus credits.\n]]\n\nlocal Workspace = game:GetService(\"Workspace\")\nlocal Players = game:GetService(\"Players\")\n\nlocal Shared = game:GetService(\"ReplicatedStorage\"):WaitForChild(\"PanicShiftShared\")\nlocal Types = require(Shared:WaitForChild(\"Types\"))\nlocal Utility = require(Shared:WaitForChild(\"Utility\"))\n\nlocal RunawayCarts = {\n    Name = \"RunawayCarts\",\n}\n\nlocal activeCarts: { Model } = {}\nlocal moverThread: thread? = nil\nlocal cartsFolder: Folder? = nil\n\n-- Constructs a physical shopping cart model\nlocal function createCart(spawnCFrame: CFrame, parentFolder: Folder): Model\n    local cartModel = Instance.new(\"Model\")\n    cartModel.Name = \"RunawayCart\"\n    cartModel.Parent = parentFolder\n\n    -- Basket Body\n    local basket = Instance.new(\"Part\")\n    basket.Name = \"Basket\"\n    basket.Size = Vector3.new(3.5, 3.0, 4.5)\n    basket.CFrame = spawnCFrame\n    basket.Color = Color3.fromRGB(180, 185, 195)\n    basket.Material = Enum.Material.Metal\n    basket.CanCollide = true\n    basket.Anchored = false\n    basket.CustomPhysicalProperties = PhysicalProperties.new(0.7, 0.1, 0.6) -- Low friction, bouncy\n    basket.Parent = cartModel\n    cartModel.PrimaryPart = basket\n\n    -- Handlebar\n    local handle = Instance.new(\"Part\")\n    handle.Name = \"Handle\"\n    handle.Size = Vector3.new(3.6, 0.4, 0.4)\n    handle.CFrame = spawnCFrame * CFrame.new(0, 1.2, 2.2)\n    handle.Color = Color3.fromRGB(235, 95, 20) -- Panic Shift Orange\n    handle.Material = Enum.Material.SmoothPlastic\n    handle.CanCollide = false\n    handle.Anchored = false\n    handle.Parent = cartModel\n\n    local weld = Instance.new(\"WeldConstraint\")\n    weld.Part0 = basket\n    weld.Part1 = handle\n    weld.Parent = basket\n\n    -- Directional Mover\n    local linearVelocity = Instance.new(\"LinearVelocity\")\n    linearVelocity.Name = \"CartMover\"\n    linearVelocity.MaxForce = 15000\n    linearVelocity.VectorVelocity = spawnCFrame.LookVector * 28 -- High speed cart\n    linearVelocity.VelocityConstraintMode = Enum.VelocityConstraintMode.Vector\n\n    local attachment = Instance.new(\"Attachment\")\n    attachment.Parent = basket\n    linearVelocity.Attachment0 = attachment\n    linearVelocity.Parent = basket\n\n    -- Proximity Prompt to wrangle/push cart\n    local prompt = Instance.new(\"ProximityPrompt\")\n    prompt.ActionText = \"Wrangle Cart\"\n    prompt.ObjectText = \"Runaway Shopping Cart\"\n    prompt.HoldDuration = 0.5\n    prompt.MaxActivationDistance = 9\n    prompt.Parent = basket\n\n    -- Player hit detection (comedic stumble)\n    local debounce = false\n    basket.Touched:Connect(function(otherPart: BasePart)\n        if debounce then return end\n        local char = otherPart.Parent\n        local humanoid = char and char:FindFirstChildOfClass(\"Humanoid\")\n        if humanoid and not debounce then\n            debounce = true\n            -- Knock back and brief stumble\n            local root = char:FindFirstChild(\"HumanoidRootPart\") :: BasePart?\n            if root then\n                root.AssemblyLinearVelocity = (root.Position - basket.Position).Unit * 35 + Vector3.new(0, 15, 0)\n            end\n            task.delay(1.5, function()\n                debounce = false\n            end)\n        end\n    end)\n\n    return cartModel\nend\n\nfunction RunawayCarts.CanStart(context: Types.DisasterContext?): boolean\n    local map = context and context.SupermarketMap or Workspace:FindFirstChild(\"SupermarketMap\")\n    return map ~= nil\nend\n\nfunction RunawayCarts.Start(context: Types.DisasterContext): ()\n    print(\"[Disaster: RunawayCarts] Starting! Rattling cart wheels echoing across aisles.\")\n\n    cartsFolder = Instance.new(\"Folder\")\n    cartsFolder.Name = \"ActiveRunawayCarts\"\n    cartsFolder.Parent = Workspace\n\n    -- Spawn 5 runaway carts at aisle entrances\n    local spawnPositions = {\n        CFrame.new(-45, 3, -15) * CFrame.Angles(0, 0, 0),\n        CFrame.new(-15, 3, 35) * CFrame.Angles(0, math.rad(180), 0),\n        CFrame.new(15, 3, -15) * CFrame.Angles(0, 0, 0),\n        CFrame.new(45, 3, 35) * CFrame.Angles(0, math.rad(180), 0),\n        CFrame.new(0, 3, 10) * CFrame.Angles(0, math.rad(90), 0),\n    }\n\n    for _, cframe in ipairs(spawnPositions) do\n        if cartsFolder then\n            local cart = createCart(cframe, cartsFolder)\n            table.insert(activeCarts, cart)\n        end\n    end\n\n    -- Mover loop: occasionally change cart directions so they bounce through aisles\n    moverThread = task.spawn(function()\n        while true do\n            task.wait(3.5)\n            for _, cart in ipairs(activeCarts) do\n                if cart.PrimaryPart then\n                    local mover = cart.PrimaryPart:FindFirstChild(\"CartMover\") :: LinearVelocity?\n                    if mover then\n                        local randomAngle = math.rad(math.random(0, 3) * 90)\n                        mover.VectorVelocity = Vector3.new(math.cos(randomAngle) * 26, 0, math.sin(randomAngle) * 26)\n                    end\n                end\n            end\n        end\n    end)\nend\n\nfunction RunawayCarts.Stop(context: Types.DisasterContext?): ()\n    print(\"[Disaster: RunawayCarts] Stopped and cleaned up.\")\n    if moverThread then\n        task.cancel(moverThread)\n        moverThread = nil\n    end\n\n    if cartsFolder then\n        cartsFolder:Destroy()\n        cartsFolder = nil\n    end\n\n    for _, cart in ipairs(activeCarts) do\n        if cart and cart.Parent then\n            cart:Destroy()\n        end\n    end\n    table.clear(activeCarts)\nend\n\nreturn RunawayCarts\n")
setScript(getOrCreateFolder(game:GetService("ServerStorage"), "DisasterModules"), "SoapApocalypse", "ModuleScript", "--!strict\n--[[\n    PANIC SHIFT: Disaster - SoapApocalypse.lua\n    Disaster 5: Detergent vents rupture, coating supermarket floors with soapy foam.\n    Floor friction drops to near-zero (ice skating physics).\n]]\n\nlocal Workspace = game:GetService(\"Workspace\")\n\nlocal Shared = game:GetService(\"ReplicatedStorage\"):WaitForChild(\"PanicShiftShared\")\nlocal Types = require(Shared:WaitForChild(\"Types\"))\n\nlocal SoapApocalypse = {\n    Name = \"SoapApocalypse\",\n}\n\nlocal soapFolder: Folder? = nil\nlocal modifiedFloorParts: { { part: BasePart, originalProperties: PhysicalProperties? } } = {}\n\nfunction SoapApocalypse.CanStart(context: Types.DisasterContext?): boolean\n    local map = context and context.SupermarketMap or Workspace:FindFirstChild(\"SupermarketMap\")\n    return map ~= nil\nend\n\nfunction SoapApocalypse.Start(context: Types.DisasterContext): ()\n    print(\"[Disaster: SoapApocalypse] Detergent vents ruptured! Floors are frictionless ice!\")\n\n    local map = context.SupermarketMap or Workspace:FindFirstChild(\"SupermarketMap\")\n    if not map then return end\n\n    soapFolder = Instance.new(\"Folder\")\n    soapFolder.Name = \"ActiveSoapApocalypse\"\n    soapFolder.Parent = Workspace\n\n    -- 1. Modify floor friction to 0.01 (frictionless sliding)\n    local arch = map:FindFirstChild(\"Architecture\")\n    if arch then\n        for _, child in ipairs(arch:GetChildren()) do\n            if child.Name:find(\"Floor\") and child:IsA(\"BasePart\") then\n                table.insert(modifiedFloorParts, {\n                    part = child,\n                    originalProperties = child.CustomPhysicalProperties,\n                })\n                -- Zero friction, slight bounciness\n                child.CustomPhysicalProperties = PhysicalProperties.new(0.01, 0.01, 0.2)\n            end\n        end\n    end\n\n    -- 2. Spawn floating soap bubble emitters from ceiling\n    for x = -40, 40, 20 do\n        for z = -10, 40, 20 do\n            local ventBubble = Instance.new(\"Part\")\n            ventBubble.Name = \"SoapVent\"\n            ventBubble.Size = Vector3.new(2, 0.4, 2)\n            ventBubble.CFrame = CFrame.new(x, 20, z)\n            ventBubble.Transparency = 1\n            ventBubble.Anchored = true\n            ventBubble.CanCollide = false\n            ventBubble.Parent = soapFolder\n\n            local bubbles = Instance.new(\"ParticleEmitter\")\n            bubbles.Rate = 12\n            bubbles.Speed = NumberRange.new(2, 6)\n            bubbles.Lifetime = NumberRange.new(3, 6)\n            bubbles.SpreadAngle = Vector2.new(180, 180)\n            bubbles.Size = NumberSequence.new(0.6, 1.4)\n            bubbles.Color = ColorSequence.new(Color3.fromRGB(240, 245, 255))\n            bubbles.Parent = ventBubble\n        end\n    end\nend\n\nfunction SoapApocalypse.Stop(context: Types.DisasterContext?): ()\n    print(\"[Disaster: SoapApocalypse] Cleaning crew squeegeed the floor. Normal traction restored.\")\n\n    -- Restore floor properties\n    for _, item in ipairs(modifiedFloorParts) do\n        if item.part and item.part.Parent then\n            if item.originalProperties then\n                item.part.CustomPhysicalProperties = item.originalProperties\n            else\n                item.part.CustomPhysicalProperties = PhysicalProperties.new(0.7, 0.3, 0.5)\n            end\n        end\n    end\n    table.clear(modifiedFloorParts)\n\n    if soapFolder then\n        soapFolder:Destroy()\n        soapFolder = nil\n    end\nend\n\nreturn SoapApocalypse\n")
setScript(getOrCreateFolder(game:GetService("ServerScriptService"), "Services"), "AnalyticsService", "ModuleScript", "--!strict\n--[[\n    PANIC SHIFT: AnalyticsService.lua\n    Server-side telemetry and event logging for gameplay funnels,\n    retention indicators, and balancing metrics.\n]]\n\nlocal AnalyticsService = {\n    Name = \"AnalyticsService\",\n}\n\nlocal services: { [string]: any } = {}\nlocal eventLog: { { Timestamp: number, Event: string, Params: { [string]: any } } } = {}\n\nfunction AnalyticsService:Init(serviceRegistry: { [string]: any })\n    services = serviceRegistry\nend\n\nfunction AnalyticsService:Start()\n    print(\"[PanicShift AnalyticsService] Initialized telemetry pipeline.\")\nend\n\n-- Records a structured telemetry event\nfunction AnalyticsService:LogEvent(eventName: string, params: { [string]: any }): ()\n    local entry = {\n        Timestamp = os.time(),\n        Event = eventName,\n        Params = params or {},\n    }\n\n    table.insert(eventLog, entry)\n    \n    -- Print structured telemetry for development/debugging\n    local details = \"\"\n    for k, v in pairs(entry.Params) do\n        details = details .. string.format(\" %s=%s\", tostring(k), tostring(v))\n    end\n    print(string.format(\"[Telemetry] %s:%s\", eventName, details))\n\n    -- Keep memory footprint capped\n    if #eventLog > 500 then\n        table.remove(eventLog, 1)\n    end\nend\n\nreturn AnalyticsService\n")
setScript(getOrCreateFolder(game:GetService("ServerScriptService"), "Services"), "ChallengeService", "ModuleScript", "--!strict\n--[[\n    PANIC SHIFT: ChallengeService.lua\n    Manages daily challenge rotation, tracking, and objective completion.\n]]\n\nlocal Shared = game:GetService(\"ReplicatedStorage\"):WaitForChild(\"PanicShiftShared\")\nlocal Types = require(Shared:WaitForChild(\"Types\"))\nlocal Config = require(Shared:WaitForChild(\"Config\"))\n\nlocal ChallengeService = {\n    Name = \"ChallengeService\",\n}\n\nlocal services: { [string]: any } = {}\n\nfunction ChallengeService:Init(serviceRegistry: { [string]: any })\n    services = serviceRegistry\nend\n\nfunction ChallengeService:Start()\n    -- Daily challenge tracking ready\nend\n\n-- Checks and resets daily challenge data if day has rolled over\nfunction ChallengeService:VerifyDailyReset(player: Player): ()\n    local dataService = services.DataService\n    if not dataService then\n        return\n    end\n\n    local currentKey = os.date(\"!%Y-%m-%d\")\n    dataService:UpdateProfile(player, function(profile: Types.PlayerProfile)\n        if profile.dailyChallenges.resetKey ~= currentKey then\n            profile.dailyChallenges = {\n                resetKey = currentKey,\n                completed = {},\n                progress = {},\n            }\n        end\n    end)\nend\n\n-- Increments challenge progress for a specific target action\nfunction ChallengeService:IncrementProgress(player: Player, challengeId: string, amount: number): ()\n    local dataService = services.DataService\n    local economyService = services.EconomyService\n    if not dataService or not economyService then\n        return\n    end\n\n    self:VerifyDailyReset(player)\n\n    local profile = dataService:GetProfile(player)\n    if not profile or profile.dailyChallenges.completed[challengeId] then\n        return\n    end\n\n    -- Find challenge definition\n    local challengeDef = nil\n    for _, def in ipairs(Config.DailyChallenges) do\n        if def.Id == challengeId then\n            challengeDef = def\n            break\n        end\n    end\n\n    if not challengeDef then\n        return\n    end\n\n    dataService:UpdateProfile(player, function(prof: Types.PlayerProfile)\n        local current = (prof.dailyChallenges.progress[challengeId] or 0) + amount\n        prof.dailyChallenges.progress[challengeId] = current\n\n        if current >= challengeDef.TargetCount and not prof.dailyChallenges.completed[challengeId] then\n            prof.dailyChallenges.completed[challengeId] = true\n            economyService:AwardCredits(player, challengeDef.CreditReward, \"DailyChallenge_\" .. challengeId)\n            economyService:AwardXp(player, challengeDef.XpReward, \"DailyChallenge_\" .. challengeId)\n        end\n    end)\nend\n\nreturn ChallengeService\n")
setScript(getOrCreateFolder(game:GetService("ServerScriptService"), "Services"), "DataService", "ModuleScript", "--!strict\n--[[\n    PANIC SHIFT: DataService.lua\n    Authoritative player data persistence. Implements schema versioning,\n    session caching, exponential backoff retries, corruption prevention,\n    and an in-memory mock store for safe Studio and offline testing.\n]]\n\nlocal DataStoreService = game:GetService(\"DataStoreService\")\nlocal Players = game:GetService(\"Players\")\nlocal RunService = game:GetService(\"RunService\")\n\nlocal Shared = game:GetService(\"ReplicatedStorage\"):WaitForChild(\"PanicShiftShared\")\nlocal Types = require(Shared:WaitForChild(\"Types\"))\nlocal Utility = require(Shared:WaitForChild(\"Utility\"))\nlocal Network = require(Shared:WaitForChild(\"Network\"))\nlocal Constants = require(Shared:WaitForChild(\"Constants\"))\n\nlocal DATA_STORE_NAME = \"PanicShift_PlayerData_v1\"\nlocal CURRENT_SCHEMA_VERSION = 1\n\nlocal DataService = {\n    Name = \"DataService\",\n}\n\nlocal services: { [string]: any } = {}\nlocal profiles: { [Player]: Types.PlayerProfile } = {}\nlocal failedLoads: { [Player]: boolean } = {}\nlocal playerDataStore: any = nil\nlocal mockDataStore: { [string]: any } = {} -- Safe mock store for Studio/Test mode\n\n-- Constructs the default player profile\nfunction DataService.CreateDefaultProfile(): Types.PlayerProfile\n    return {\n        schemaVersion = CURRENT_SCHEMA_VERSION,\n        credits = 0,\n        xp = 0,\n        level = 1,\n        ownedCosmetics = { \"default_uniform\" },\n        equippedCosmetic = \"default_uniform\",\n        equippedHat = nil,\n        lifetimeStats = {\n            shiftsCompleted = 0,\n            shiftsWon = 0,\n            tasksCompleted = 0,\n            disastersSurvives = 0,\n            spillsCleaned = 0,\n            ordersDelivered = 0,\n        },\n        dailyChallenges = {\n            resetKey = os.date(\"!%Y-%m-%d\"),\n            completed = {},\n            progress = {},\n        },\n        settings = {\n            musicVolume = 0.8,\n            sfxVolume = 0.9,\n            screenShake = true,\n        },\n    }\nend\n\n-- Migrates data between schema versions safely (FR-18)\nfunction DataService.MigrateProfile(data: any): Types.PlayerProfile\n    if typeof(data) ~= \"table\" then\n        return DataService.CreateDefaultProfile()\n    end\n\n    local profile = Utility.DeepCopy(data) :: Types.PlayerProfile\n\n    -- Version 0 -> Version 1 upgrade\n    if not profile.schemaVersion or profile.schemaVersion < 1 then\n        profile.schemaVersion = 1\n        profile.credits = profile.credits or 0\n        profile.xp = profile.xp or 0\n        profile.level = profile.level or 1\n        profile.ownedCosmetics = profile.ownedCosmetics or { \"default_uniform\" }\n        profile.equippedCosmetic = profile.equippedCosmetic or \"default_uniform\"\n        profile.lifetimeStats = profile.lifetimeStats or {\n            shiftsCompleted = 0,\n            shiftsWon = 0,\n            tasksCompleted = 0,\n            disastersSurvives = 0,\n            spillsCleaned = 0,\n            ordersDelivered = 0,\n        }\n        profile.dailyChallenges = profile.dailyChallenges or {\n            resetKey = os.date(\"!%Y-%m-%d\"),\n            completed = {},\n            progress = {},\n        }\n        profile.settings = profile.settings or {\n            musicVolume = 0.8,\n            sfxVolume = 0.9,\n            screenShake = true,\n        }\n    end\n\n    return profile\nend\n\nfunction DataService:Init(serviceRegistry: { [string]: any })\n    services = serviceRegistry\n\n    local success, store = pcall(function()\n        return DataStoreService:GetDataStore(DATA_STORE_NAME)\n    end)\n\n    if success and store then\n        playerDataStore = store\n        print(\"[PanicShift DataService] Successfully connected to live DataStoreService.\")\n    else\n        warn(\"[PanicShift DataService] DataStoreService unavailable. Operating with In-Memory Mock Store.\")\n    end\nend\n\nfunction DataService:Start()\n    -- Profile loading on player join\n    Players.PlayerAdded:Connect(function(player: Player)\n        self:LoadProfile(player)\n    end)\n\n    -- Profile saving on player disconnect\n    Players.PlayerRemoving:Connect(function(player: Player)\n        self:SaveProfile(player)\n        profiles[player] = nil\n        failedLoads[player] = nil\n    end)\nend\n\nfunction DataService:LoadProfile(player: Player): Types.PlayerProfile?\n    local key = string.format(\"Player_%d\", player.UserId)\n    local loadedData: any = nil\n\n    if playerDataStore then\n        local readSuccess, result = Utility.RetryWithBackoff(3, 1.0, function()\n            local s, res = pcall(function()\n                return playerDataStore:GetAsync(key)\n            end)\n            return s, res\n        end)\n\n        if readSuccess then\n            loadedData = result\n        else\n            warn(string.format(\"[PanicShift DataService] Failed to load data for %s (UserId: %d). Enabling safe read-only fallback.\", player.Name, player.UserId))\n            failedLoads[player] = true\n            profiles[player] = DataService.CreateDefaultProfile()\n            self:SyncClient(player)\n            return profiles[player]\n        end\n    else\n        -- Read from safe local mock store\n        loadedData = mockDataStore[key]\n    end\n\n    local finalProfile: Types.PlayerProfile\n    if loadedData then\n        finalProfile = DataService.MigrateProfile(loadedData)\n    else\n        finalProfile = DataService.CreateDefaultProfile()\n    end\n\n    profiles[player] = finalProfile\n    self:SyncClient(player)\n    return finalProfile\nend\n\nfunction DataService:SaveProfile(player: Player): boolean\n    -- Critical Guard: Never overwrite data if initial load failed (FR-16 / NFR-04)\n    if failedLoads[player] then\n        warn(string.format(\"[PanicShift DataService] Save aborted for %s: initial profile read had failed. Preventing corruption overwrite.\", player.Name))\n        return false\n    end\n\n    local profile = profiles[player]\n    if not profile then\n        return false\n    end\n\n    local key = string.format(\"Player_%d\", player.UserId)\n\n    if playerDataStore then\n        local writeSuccess = Utility.RetryWithBackoff(3, 1.0, function()\n            local s, err = pcall(function()\n                playerDataStore:SetAsync(key, profile)\n            end)\n            if not s then\n                warn(\"[PanicShift DataService] DataStore write error:\", err)\n            end\n            return s, nil\n        end)\n        return writeSuccess\n    else\n        -- Save to local mock store\n        mockDataStore[key] = Utility.DeepCopy(profile)\n        return true\n    end\nend\n\nfunction DataService:GetProfile(player: Player): Types.PlayerProfile?\n    return profiles[player]\nend\n\nfunction DataService:UpdateProfile(player: Player, mutator: (profile: Types.PlayerProfile) -> ()): boolean\n    local profile = profiles[player]\n    if not profile then\n        return false\n    end\n\n    mutator(profile)\n    self:SyncClient(player)\n    return true\nend\n\nfunction DataService:SyncClient(player: Player)\n    local profile = profiles[player]\n    if not profile then\n        return\n    end\n\n    local success, remote = pcall(function()\n        return Network.GetRemoteEvent(Constants.Remotes.PLAYER_PROFILE_UPDATED)\n    end)\n    if success and remote then\n        remote:FireClient(player, profile)\n    end\nend\n\nfunction DataService:SaveAll()\n    for _, player in ipairs(Players:GetPlayers()) do\n        self:SaveProfile(player)\n    end\nend\n\n-- Test helper methods for automated validation\nfunction DataService._InjectMockFailure(player: Player)\n    failedLoads[player] = true\nend\n\nfunction DataService._IsSaveBlocked(player: Player): boolean\n    return failedLoads[player] == true\nend\n\nreturn DataService\n")
setScript(getOrCreateFolder(game:GetService("ServerScriptService"), "Services"), "DisasterService", "ModuleScript", "--!strict\n--[[\n    PANIC SHIFT: DisasterService.lua\n    The Disaster Director. Manages disaster weighted selection, telegraph countdowns,\n    module lifecycle execution, and guaranteed fail-safe cleanup.\n]]\n\nlocal ServerStorage = game:GetService(\"ServerStorage\")\nlocal RunService = game:GetService(\"RunService\")\n\nlocal Shared = game:GetService(\"ReplicatedStorage\"):WaitForChild(\"PanicShiftShared\")\nlocal Types = require(Shared:WaitForChild(\"Types\"))\nlocal Config = require(Shared:WaitForChild(\"Config\"))\nlocal Constants = require(Shared:WaitForChild(\"Constants\"))\nlocal Network = require(Shared:WaitForChild(\"Network\"))\n\nlocal DisasterService = {\n    Name = \"DisasterService\",\n}\n\nlocal services: { [string]: any } = {}\nlocal disasterModules: { [string]: any } = {}\nlocal activeDisasterId: string? = nil\nlocal activeDisasterModule: any = nil\nlocal activeDisasterContext: Types.DisasterContext? = nil\nlocal disasterStopThread: thread? = nil\n\nfunction DisasterService:Init(serviceRegistry: { [string]: any })\n    services = serviceRegistry\n\n    -- Dynamically locate and register disaster modules\n    local storageFolder = ServerStorage:FindFirstChild(\"PanicShiftStorage\")\n    local modulesFolder = storageFolder and storageFolder:FindFirstChild(\"DisasterModules\") or ServerStorage:FindFirstChild(\"DisasterModules\")\n\n    if modulesFolder then\n        for _, child in ipairs(modulesFolder:GetChildren()) do\n            if child:IsA(\"ModuleScript\") then\n                local success, disasterMod = pcall(function()\n                    return require(child)\n                end)\n                if success and typeof(disasterMod) == \"table\" then\n                    disasterModules[child.Name] = disasterMod\n                else\n                    warn(string.format(\"[PanicShift DisasterService] Failed to load module %s\", child.Name))\n                end\n            end\n        end\n    end\nend\n\nfunction DisasterService:Start()\n    -- Ready for shift disasters\nend\n\n-- Weighted random selection of the next disaster\nfunction DisasterService:SelectNextDisaster(): string?\n    local eligible: { { id: string, weight: number } } = {}\n    local totalWeight = 0\n\n    for id, weight in pairs(Config.Disasters.Weights) do\n        -- Exclude currently active disaster\n        if id ~= activeDisasterId and disasterModules[id] then\n            local mod = disasterModules[id]\n            local canStart = true\n            if typeof(mod.CanStart) == \"function\" then\n                canStart = mod.CanStart()\n            end\n            if canStart then\n                table.insert(eligible, { id = id, weight = weight })\n                totalWeight = totalWeight + weight\n            end\n        end\n    end\n\n    if totalWeight <= 0 or #eligible == 0 then\n        return nil\n    end\n\n    local roll = math.random(1, totalWeight)\n    local accumulated = 0\n    for _, item in ipairs(eligible) do\n        accumulated = accumulated + item.weight\n        if roll <= accumulated then\n            return item.id\n        end\n    end\n\n    return eligible[1].id\nend\n\n-- Initiates a disaster event with telegraphing and scheduled cleanup\nfunction DisasterService:TriggerDisaster(disasterId: string, customDuration: number?): boolean\n    if activeDisasterId then\n        self:StopActiveDisaster()\n    end\n\n    local mod = disasterModules[disasterId]\n    if not mod then\n        warn(string.format(\"[PanicShift DisasterService] Disaster module '%s' not registered!\", disasterId))\n        return false\n    end\n\n    local duration = customDuration or Config.Disasters.Durations[disasterId] or 25\n    local telegraphDuration = Config.Disasters.TelegraphDuration\n\n    local context: Types.DisasterContext = {\n        RoundId = services.RoundService and services.RoundService:GetCurrentRoundId() or \"DevShift\",\n        Duration = duration,\n        SupermarketMap = services.RoundService and services.RoundService:GetSupermarketMap() or nil,\n        Services = services,\n        TelegraphDuration = telegraphDuration,\n    }\n\n    activeDisasterId = disasterId\n    activeDisasterModule = mod\n    activeDisasterContext = context\n\n    -- Broadcast telegraph warning\n    local remote = Network.GetRemoteEvent(Constants.Remotes.DISASTER_STATE_CHANGED)\n    remote:FireAllClients(disasterId, Constants.DisasterStatus.TELEGRAPH, telegraphDuration, {\n        Duration = duration,\n    })\n\n    if services.AnalyticsService then\n        services.AnalyticsService:LogEvent(\"DisasterTelegraph\", { DisasterId = disasterId })\n    end\n\n    -- Run disaster execution in a dedicated task thread\n    disasterStopThread = task.spawn(function()\n        task.wait(telegraphDuration)\n\n        if activeDisasterId ~= disasterId then\n            return -- Was cancelled during telegraph\n        end\n\n        remote:FireAllClients(disasterId, Constants.DisasterStatus.ACTIVE, duration, {})\n\n        -- Protected start execution\n        local startOk, startErr = pcall(function()\n            if typeof(mod.Start) == \"function\" then\n                mod.Start(context)\n            end\n        end)\n\n        if not startOk then\n            warn(string.format(\"[PanicShift DisasterService] Disaster %s Start() errored: %s\", disasterId, tostring(startErr)))\n        end\n\n        task.wait(duration)\n\n        -- Natural expiration\n        if activeDisasterId == disasterId then\n            self:StopActiveDisaster()\n        end\n    end)\n\n    return true\nend\n\n-- Guaranteed safe cleanup of active disaster\nfunction DisasterService:StopActiveDisaster(): ()\n    if not activeDisasterId then\n        return\n    end\n\n    local currentId = activeDisasterId\n    local currentMod = activeDisasterModule\n    local currentCtx = activeDisasterContext\n\n    if disasterStopThread then\n        task.cancel(disasterStopThread)\n        disasterStopThread = nil\n    end\n\n    activeDisasterId = nil\n    activeDisasterModule = nil\n    activeDisasterContext = nil\n\n    if currentMod and typeof(currentMod.Stop) == \"function\" then\n        local ok, err = pcall(function()\n            currentMod.Stop(currentCtx)\n        end)\n        if not ok then\n            warn(string.format(\"[PanicShift DisasterService] Error during %s Stop(): %s\", currentId, tostring(err)))\n        end\n    end\n\n    local remote = Network.GetRemoteEvent(Constants.Remotes.DISASTER_STATE_CHANGED)\n    remote:FireAllClients(currentId, Constants.DisasterStatus.COMPLETED, 0, {})\n\n    if services.AnalyticsService then\n        services.AnalyticsService:LogEvent(\"DisasterEnded\", { DisasterId = currentId })\n    end\nend\n\nfunction DisasterService:IsDisasterActive(): boolean\n    return activeDisasterId ~= nil\nend\n\nreturn DisasterService\n")
setScript(getOrCreateFolder(game:GetService("ServerScriptService"), "Services"), "EconomyService", "ModuleScript", "--!strict\n--[[\n    PANIC SHIFT: EconomyService.lua\n    Server-authoritative wallet and progression manager.\n    Enforces atomic credit/XP modifications, level scaling, and audit logging.\n]]\n\nlocal Shared = game:GetService(\"ReplicatedStorage\"):WaitForChild(\"PanicShiftShared\")\nlocal Types = require(Shared:WaitForChild(\"Types\"))\nlocal Config = require(Shared:WaitForChild(\"Config\"))\n\nlocal EconomyService = {\n    Name = \"EconomyService\",\n}\n\nlocal services: { [string]: any } = {}\n\nfunction EconomyService:Init(serviceRegistry: { [string]: any })\n    services = serviceRegistry\nend\n\nfunction EconomyService:Start()\n    -- Ready for shift operations\nend\n\n-- Safely retrieves player wallet balance\nfunction EconomyService:GetBalance(player: Player): number\n    local dataService = services.DataService\n    if not dataService then\n        return 0\n    end\n\n    local profile = dataService:GetProfile(player)\n    return profile and profile.credits or 0\nend\n\n-- Atomically awards credits with logging\nfunction EconomyService:AwardCredits(player: Player, amount: number, reason: string): boolean\n    if amount <= 0 then\n        return false\n    end\n\n    local dataService = services.DataService\n    if not dataService then\n        return false\n    end\n\n    return dataService:UpdateProfile(player, function(profile: Types.PlayerProfile)\n        profile.credits = profile.credits + amount\n    end)\nend\n\n-- Atomically deducts credits with balance verification\nfunction EconomyService:DeductCredits(player: Player, amount: number): boolean\n    if amount <= 0 then\n        return false\n    end\n\n    local dataService = services.DataService\n    if not dataService then\n        return false\n    end\n\n    local currentBalance = self:GetBalance(player)\n    if currentBalance < amount then\n        return false\n    end\n\n    return dataService:UpdateProfile(player, function(profile: Types.PlayerProfile)\n        profile.credits = profile.credits - amount\n    end)\nend\n\n-- Awards XP and evaluates progressive level-ups\nfunction EconomyService:AwardXp(player: Player, amount: number, reason: string): (boolean, boolean)\n    if amount <= 0 then\n        return false, false\n    end\n\n    local dataService = services.DataService\n    if not dataService then\n        return false, false\n    end\n\n    local didLevelUp = false\n\n    local updated = dataService:UpdateProfile(player, function(profile: Types.PlayerProfile)\n        profile.xp = profile.xp + amount\n\n        -- Check level up thresholds\n        local nextLevelRequirement = Config.Progression.CalculateRequiredXp(profile.level)\n        while profile.xp >= nextLevelRequirement do\n            profile.xp = profile.xp - nextLevelRequirement\n            profile.level = profile.level + 1\n            didLevelUp = true\n            nextLevelRequirement = Config.Progression.CalculateRequiredXp(profile.level)\n        end\n    end)\n\n    if didLevelUp and services.AnalyticsService then\n        local profile = dataService:GetProfile(player)\n        services.AnalyticsService:LogEvent(\"PlayerLevelUp\", {\n            PlayerId = player.UserId,\n            NewLevel = profile and profile.level or 1,\n        })\n    end\n\n    return updated, didLevelUp\nend\n\nreturn EconomyService\n")
setScript(getOrCreateFolder(game:GetService("ServerScriptService"), "Services"), "InventoryService", "ModuleScript", "--!strict\n--[[\n    PANIC SHIFT: InventoryService.lua\n    Server-side cosmetic ownership and character loadout verifier.\n]]\n\nlocal Shared = game:GetService(\"ReplicatedStorage\"):WaitForChild(\"PanicShiftShared\")\nlocal Types = require(Shared:WaitForChild(\"Types\"))\nlocal Config = require(Shared:WaitForChild(\"Config\"))\nlocal Constants = require(Shared:WaitForChild(\"Constants\"))\nlocal Utility = require(Shared:WaitForChild(\"Utility\"))\nlocal Network = require(Shared:WaitForChild(\"Network\"))\n\nlocal InventoryService = {\n    Name = \"InventoryService\",\n}\n\nlocal services: { [string]: any } = {}\nlocal rateLimiter: (key: any) -> boolean\n\nfunction InventoryService:Init(serviceRegistry: { [string]: any })\n    services = serviceRegistry\n    rateLimiter = Utility.CreateRateLimiter(Config.RateLimits.EQUIP_MAX_PER_SECOND, 1.0)\nend\n\nfunction InventoryService:Start()\n    local equipFunc = Network.GetRemoteFunction(Constants.Remotes.REQUEST_EQUIP_COSMETIC)\n    equipFunc.OnServerInvoke = function(player: Player, cosmeticId: any, slot: any): Types.NetworkResponse\n        return self:HandleEquipRequest(player, cosmeticId, slot)\n    end\nend\n\n-- Checks if player owns a specific cosmetic\nfunction InventoryService:OwnsCosmetic(player: Player, cosmeticId: string): boolean\n    local dataService = services.DataService\n    if not dataService then\n        return false\n    end\n\n    local profile = dataService:GetProfile(player)\n    if not profile then\n        return false\n    end\n\n    for _, ownedId in ipairs(profile.ownedCosmetics) do\n        if ownedId == cosmeticId then\n            return true\n        end\n    end\n\n    return false\nend\n\n-- Validates and applies character cosmetic equip\nfunction InventoryService:HandleEquipRequest(player: Player, cosmeticId: any, slot: any): Types.NetworkResponse\n    -- Anti-exploit: Rate limit check\n    if not rateLimiter(player.UserId) then\n        return Utility.CreateErrorResponse(Constants.ErrorCodes.RATE_LIMITED, \"Equip requests are rate-limited.\")\n    end\n\n    -- Argument validation\n    if typeof(cosmeticId) ~= \"string\" or typeof(slot) ~= \"string\" then\n        return Utility.CreateErrorResponse(Constants.ErrorCodes.INVALID_ARGUMENTS, \"Invalid cosmetic request parameters.\")\n    end\n\n    local itemDef = Config.Cosmetics[cosmeticId]\n    if not itemDef then\n        return Utility.CreateErrorResponse(Constants.ErrorCodes.INVALID_ARGUMENTS, \"Cosmetic item does not exist.\")\n    end\n\n    if not self:OwnsCosmetic(player, cosmeticId) then\n        return Utility.CreateErrorResponse(Constants.ErrorCodes.ITEM_NOT_OWNED, \"You do not own this cosmetic.\")\n    end\n\n    local dataService = services.DataService\n    if not dataService then\n        return Utility.CreateErrorResponse(Constants.ErrorCodes.PROFILE_NOT_LOADED, \"Profile unavailable.\")\n    end\n\n    local success = dataService:UpdateProfile(player, function(profile: Types.PlayerProfile)\n        if itemDef.Type == \"Uniform\" then\n            profile.equippedCosmetic = cosmeticId\n        elseif itemDef.Type == \"Headwear\" then\n            profile.equippedHat = cosmeticId\n        end\n    end)\n\n    if success then\n        return Utility.CreateSuccessResponse({ EquippedId = cosmeticId, Slot = slot })\n    else\n        return Utility.CreateErrorResponse(Constants.ErrorCodes.INVALID_STATE, \"Failed to update profile.\")\n    end\nend\n\nreturn InventoryService\n")
setScript(getOrCreateFolder(game:GetService("ServerScriptService"), "Services"), "PurchaseService", "ModuleScript", "--!strict\n--[[\n    PANIC SHIFT: PurchaseService.lua\n    Manages in-game cosmetic store transactions and receipt validation.\n    Guarantees atomic credit deduction and prevents duplicate unlocks.\n]]\n\nlocal MarketplaceService = game:GetService(\"MarketplaceService\")\n\nlocal Shared = game:GetService(\"ReplicatedStorage\"):WaitForChild(\"PanicShiftShared\")\nlocal Types = require(Shared:WaitForChild(\"Types\"))\nlocal Config = require(Shared:WaitForChild(\"Config\"))\nlocal Constants = require(Shared:WaitForChild(\"Constants\"))\nlocal Utility = require(Shared:WaitForChild(\"Utility\"))\nlocal Network = require(Shared:WaitForChild(\"Network\"))\n\nlocal PurchaseService = {\n    Name = \"PurchaseService\",\n}\n\nlocal services: { [string]: any } = {}\nlocal rateLimiter: (key: any) -> boolean\n\nfunction PurchaseService:Init(serviceRegistry: { [string]: any })\n    services = serviceRegistry\n    rateLimiter = Utility.CreateRateLimiter(Config.RateLimits.PURCHASE_MAX_PER_SECOND, 1.0)\nend\n\nfunction PurchaseService:Start()\n    local purchaseFunc = Network.GetRemoteFunction(Constants.Remotes.REQUEST_PURCHASE_COSMETIC)\n    purchaseFunc.OnServerInvoke = function(player: Player, cosmeticId: any): Types.NetworkResponse\n        return self:HandlePurchaseRequest(player, cosmeticId)\n    end\nend\n\n-- Processes soft-currency (Store Credits) purchases\nfunction PurchaseService:HandlePurchaseRequest(player: Player, cosmeticId: any): Types.NetworkResponse\n    -- Rate limit protection\n    if not rateLimiter(player.UserId) then\n        return Utility.CreateErrorResponse(Constants.ErrorCodes.RATE_LIMITED, \"Purchase requests are throttled.\")\n    end\n\n    if typeof(cosmeticId) ~= \"string\" then\n        return Utility.CreateErrorResponse(Constants.ErrorCodes.INVALID_ARGUMENTS, \"Invalid cosmetic ID.\")\n    end\n\n    local itemDef = Config.Cosmetics[cosmeticId]\n    if not itemDef then\n        return Utility.CreateErrorResponse(Constants.ErrorCodes.INVALID_ARGUMENTS, \"Cosmetic item not found in catalog.\")\n    end\n\n    local inventoryService = services.InventoryService\n    local economyService = services.EconomyService\n    local dataService = services.DataService\n\n    if not inventoryService or not economyService or not dataService then\n        return Utility.CreateErrorResponse(Constants.ErrorCodes.INVALID_STATE, \"Internal services unavailable.\")\n    end\n\n    -- Verify not already owned\n    if inventoryService:OwnsCosmetic(player, cosmeticId) then\n        return Utility.CreateErrorResponse(Constants.ErrorCodes.INVALID_STATE, \"You already own this item.\")\n    end\n\n    -- Verify wallet balance\n    local currentBalance = economyService:GetBalance(player)\n    if currentBalance < itemDef.Price then\n        return Utility.CreateErrorResponse(Constants.ErrorCodes.INSUFFICIENT_FUNDS, \"Insufficient Store Credits.\")\n    end\n\n    -- Atomic transaction: deduct credits and append to inventory\n    local deductSuccess = economyService:DeductCredits(player, itemDef.Price)\n    if not deductSuccess then\n        return Utility.CreateErrorResponse(Constants.ErrorCodes.INSUFFICIENT_FUNDS, \"Failed to complete transaction.\")\n    end\n\n    local unlockSuccess = dataService:UpdateProfile(player, function(profile: Types.PlayerProfile)\n        table.insert(profile.ownedCosmetics, cosmeticId)\n    end)\n\n    if unlockSuccess then\n        if services.AnalyticsService then\n            services.AnalyticsService:LogEvent(\"CosmeticPurchased\", {\n                PlayerId = player.UserId,\n                ItemId = cosmeticId,\n                Price = itemDef.Price,\n            })\n        end\n\n        return Utility.CreateSuccessResponse({\n            PurchasedId = cosmeticId,\n            NewBalance = economyService:GetBalance(player),\n        })\n    else\n        -- Rollback in extreme case\n        economyService:AwardCredits(player, itemDef.Price, \"Transaction_Rollback\")\n        return Utility.CreateErrorResponse(Constants.ErrorCodes.INVALID_STATE, \"Profile unlock write failed.\")\n    end\nend\n\nreturn PurchaseService\n")
setScript(getOrCreateFolder(game:GetService("ServerScriptService"), "Services"), "RoundService", "ModuleScript", "--!strict\n--[[\n    PANIC SHIFT: RoundService.lua\n    Authoritative round lifecycle state machine. Manages lobby wait,\n    preparation countdown, main shift quotas, closing rush, results, and resets.\n    Strictly validates allowed state transitions and manages player teleportation.\n]]\n\nlocal Players = game:GetService(\"Players\")\n\nlocal Shared = game:GetService(\"ReplicatedStorage\"):WaitForChild(\"PanicShiftShared\")\nlocal Types = require(Shared:WaitForChild(\"Types\"))\nlocal Config = require(Shared:WaitForChild(\"Config\"))\nlocal Constants = require(Shared:WaitForChild(\"Constants\"))\nlocal Utility = require(Shared:WaitForChild(\"Utility\"))\nlocal Network = require(Shared:WaitForChild(\"Network\"))\n\nlocal RoundService = {\n    Name = \"RoundService\",\n}\n\nlocal services: { [string]: any } = {}\nlocal currentState: Types.RoundState = \"LOBBY\"\nlocal currentRoundId: string = \"\"\nlocal stateTimer: number = 0\nlocal currentQuota: number = 0\nlocal targetQuota: number = 0\nlocal playerContributions: { [number]: { TasksCompleted: number, CreditsEarned: number, XpEarned: number } } = {}\nlocal disasterTimer: number = 0\nlocal nextDisasterInterval: number = 35\n\n-- State Transition Validation Matrix (FR-02)\nlocal VALID_TRANSITIONS: { [Types.RoundState]: { [Types.RoundState]: boolean } } = {\n    LOBBY = { PREPARATION = true },\n    PREPARATION = { ACTIVE = true, LOBBY = true },\n    ACTIVE = { CLOSING = true, LOBBY = true },\n    CLOSING = { RESULTS = true, LOBBY = true },\n    RESULTS = { RESET = true, LOBBY = true },\n    RESET = { LOBBY = true },\n}\n\nfunction RoundService:Init(serviceRegistry: { [string]: any })\n    services = serviceRegistry\nend\n\nfunction RoundService:Start()\n    currentRoundId = Utility.GenerateUUID()\n    self:ForceState(\"LOBBY\")\n\n    -- Authoritative server tick loop\n    task.spawn(function()\n        while true do\n            self:Tick(1.0)\n            task.wait(1.0)\n        end\n    end)\nend\n\nfunction RoundService:GetCurrentRoundId(): string\n    return currentRoundId\nend\n\nfunction RoundService:GetState(): Types.RoundState\n    return currentState\nend\n\nfunction RoundService:GetTimerRemaining(): number\n    return stateTimer\nend\n\nfunction RoundService:GetQuotaProgress(): (number, number)\n    return currentQuota, targetQuota\nend\n\nfunction RoundService:GetSupermarketMap(): Model?\n    return workspace:FindFirstChild(\"SupermarketMap\") :: Model?\nend\n\n-- Teleports players to a target location\nlocal function teleportAllPlayers(targetCFrame: CFrame)\n    for _, player in ipairs(Players:GetPlayers()) do\n        local character = player.Character\n        if character and character.PrimaryPart then\n            character:PivotTo(targetCFrame + Vector3.new(math.random(-4, 4), 0, math.random(-4, 4)))\n        end\n    end\nend\n\n-- Unconditionally forces a state (used for initial startup or hard reset)\nfunction RoundService:ForceState(newState: Types.RoundState)\n    currentState = newState\n    self:ApplyStateLogic(newState)\nend\n\n-- Validates and applies state transition (rejects invalid transitions)\nfunction RoundService:SetState(newState: Types.RoundState): boolean\n    if currentState == newState then\n        return true\n    end\n\n    local allowed = VALID_TRANSITIONS[currentState]\n    if not allowed or not allowed[newState] then\n        warn(string.format(\"[RoundService] INVALID STATE TRANSITION REJECTED: %s -> %s\", currentState, newState))\n        return false\n    end\n\n    currentState = newState\n    self:ApplyStateLogic(newState)\n    return true\nend\n\nfunction RoundService:ApplyStateLogic(newState: Types.RoundState)\n    if newState == \"LOBBY\" then\n        stateTimer = Config.RoundTimers.LOBBY_DURATION\n        currentQuota = 0\n        targetQuota = 0\n        table.clear(playerContributions)\n\n    elseif newState == \"PREPARATION\" then\n        stateTimer = Config.RoundTimers.PREPARATION_DURATION\n        currentRoundId = Utility.GenerateUUID()\n        table.clear(playerContributions)\n\n        local playerCount = math.max(1, #Players:GetPlayers())\n        targetQuota = Config.QuotaConfig.BASE_QUOTA + (playerCount * Config.QuotaConfig.QUOTA_PER_PLAYER)\n        currentQuota = 0\n\n        disasterTimer = 0\n        nextDisasterInterval = math.random(Config.Disasters.IntervalMin, Config.Disasters.IntervalMax)\n\n        -- Populate initial tasks on supermarket floor\n        if services.TaskService then\n            services.TaskService:PopulateInitialTasks()\n        end\n\n        -- Teleport players to store entrance\n        teleportAllPlayers(CFrame.new(0, 3, -35))\n\n    elseif newState == \"ACTIVE\" then\n        stateTimer = Config.RoundTimers.MAIN_SHIFT_DURATION\n\n    elseif newState == \"CLOSING\" then\n        stateTimer = Config.RoundTimers.CLOSING_RUSH_DURATION\n\n    elseif newState == \"RESULTS\" then\n        stateTimer = Config.RoundTimers.RESULTS_DURATION\n        self:ProcessRoundResults()\n\n    elseif newState == \"RESET\" then\n        stateTimer = Config.RoundTimers.RESET_DURATION\n        self:CleanupRound()\n        -- Teleport players back to Lobby\n        teleportAllPlayers(CFrame.new(0, 3, -65))\n    end\n\n    self:BroadcastState()\n\n    if services.AnalyticsService then\n        services.AnalyticsService:LogEvent(\"RoundStateChanged\", {\n            State = newState,\n            RoundId = currentRoundId,\n        })\n    end\nend\n\n-- Broadcasts synchronized round state to all connected clients\nfunction RoundService:BroadcastState()\n    local remote = Network.GetRemoteEvent(Constants.Remotes.ROUND_STATE_CHANGED)\n    remote:FireAllClients(currentState, stateTimer, currentQuota, targetQuota)\nend\n\n-- Master authoritative clock tick\nfunction RoundService:Tick(deltaTime: number)\n    local players = Players:GetPlayers()\n    local playerCount = #players\n\n    if currentState == \"LOBBY\" then\n        if playerCount >= Config.ServerConfig.MIN_PLAYERS_TO_START then\n            stateTimer = math.max(0, stateTimer - deltaTime)\n            if stateTimer <= 0 then\n                self:SetState(\"PREPARATION\")\n            end\n        else\n            stateTimer = Config.RoundTimers.LOBBY_DURATION\n        end\n\n    elseif currentState == \"PREPARATION\" then\n        stateTimer = math.max(0, stateTimer - deltaTime)\n        if stateTimer <= 0 then\n            self:SetState(\"ACTIVE\")\n        end\n\n    elseif currentState == \"ACTIVE\" then\n        stateTimer = math.max(0, stateTimer - deltaTime)\n\n        -- Keep active tasks replenished if they run low\n        if services.TaskService and services.TaskService:GetActiveTaskCount() < 4 then\n            local map = self:GetSupermarketMap()\n            local taskAnchors = map and map:FindFirstChild(\"TaskAnchors\")\n            if taskAnchors then\n                local children = taskAnchors:GetChildren()\n                if #children > 0 then\n                    local randomAnchor = children[math.random(1, #children)]\n                    if randomAnchor:IsA(\"BasePart\") then\n                        local taskTypes = { \"CLEAN_SPILL\", \"RESTOCK\", \"DELIVER_ORDER\" }\n                        local pickedType = taskTypes[math.random(1, #taskTypes)]\n                        services.TaskService:CreateTask(pickedType, randomAnchor.Position, randomAnchor)\n                    end\n                end\n            end\n        end\n\n        -- Check disaster interval\n        disasterTimer = disasterTimer + deltaTime\n        if disasterTimer >= nextDisasterInterval then\n            disasterTimer = 0\n            nextDisasterInterval = math.random(Config.Disasters.IntervalMin, Config.Disasters.IntervalMax)\n            if services.DisasterService and not services.DisasterService:IsDisasterActive() then\n                local nextDisaster = services.DisasterService:SelectNextDisaster()\n                if nextDisaster then\n                    services.DisasterService:TriggerDisaster(nextDisaster)\n                end\n            end\n        end\n\n        if stateTimer <= 0 then\n            self:SetState(\"CLOSING\")\n        end\n\n    elseif currentState == \"CLOSING\" then\n        stateTimer = math.max(0, stateTimer - deltaTime)\n        if stateTimer <= 0 or currentQuota >= targetQuota then\n            self:SetState(\"RESULTS\")\n        end\n\n    elseif currentState == \"RESULTS\" then\n        stateTimer = math.max(0, stateTimer - deltaTime)\n        if stateTimer <= 0 then\n            self:SetState(\"RESET\")\n        end\n\n    elseif currentState == \"RESET\" then\n        stateTimer = math.max(0, stateTimer - deltaTime)\n        if stateTimer <= 0 then\n            self:SetState(\"LOBBY\")\n        end\n    end\n\n    self:BroadcastState()\nend\n\n-- Tracks team quota points and individual contribution\nfunction RoundService:AddQuotaProgress(points: number, contributingPlayer: Player?)\n    local multiplier = (currentState == \"CLOSING\") and Config.QuotaConfig.CLOSING_RUSH_MULTIPLIER or 1.0\n    local awardedPoints = math.floor(points * multiplier)\n\n    currentQuota = currentQuota + awardedPoints\n\n    if contributingPlayer then\n        local userId = contributingPlayer.UserId\n        if not playerContributions[userId] then\n            playerContributions[userId] = { TasksCompleted = 0, CreditsEarned = 0, XpEarned = 0 }\n        end\n        playerContributions[userId].TasksCompleted = playerContributions[userId].TasksCompleted + 1\n    end\n\n    self:BroadcastState()\nend\n\n-- Distributes end-of-shift rewards and produces results screen data\nfunction RoundService:ProcessRoundResults()\n    local isSuccess = currentQuota >= targetQuota\n    local teamBonus = isSuccess and 50 or 15\n\n    local mvpPlayerId: number? = nil\n    local maxTasks = -1\n\n    for userId, stats in pairs(playerContributions) do\n        if stats.TasksCompleted > maxTasks then\n            maxTasks = stats.TasksCompleted\n            mvpPlayerId = userId\n        end\n    end\n\n    local individualSummary: { [number]: any } = {}\n\n    for _, player in ipairs(Players:GetPlayers()) do\n        local stats = playerContributions[player.UserId] or { TasksCompleted = 0, CreditsEarned = 0, XpEarned = 0 }\n        local isMvp = (player.UserId == mvpPlayerId) and (stats.TasksCompleted > 0)\n        local finalCredits = teamBonus + (isMvp and 25 or 0)\n        local finalXp = isSuccess and 60 or 20\n\n        if services.EconomyService then\n            services.EconomyService:AwardCredits(player, finalCredits, \"ShiftResultBonus\")\n            services.EconomyService:AwardXp(player, finalXp, \"ShiftResultBonus\")\n        end\n\n        individualSummary[player.UserId] = {\n            PlayerName = player.Name,\n            TasksCompleted = stats.TasksCompleted,\n            CreditsEarned = finalCredits,\n            XpEarned = finalXp,\n            IsMvp = isMvp,\n        }\n    end\n\n    local resultsPayload: Types.RoundResultsData = {\n        Success = isSuccess,\n        ShiftName = \"Night Shift #\" .. string.sub(currentRoundId, -4),\n        QuotaReached = currentQuota,\n        QuotaTarget = targetQuota,\n        DurationSeconds = Config.RoundTimers.MAIN_SHIFT_DURATION + Config.RoundTimers.CLOSING_RUSH_DURATION - stateTimer,\n        TeamBonusCredits = teamBonus,\n        IndividualStats = individualSummary,\n    }\n\n    local remote = Network.GetRemoteEvent(Constants.Remotes.ROUND_RESULTS)\n    remote:FireAllClients(resultsPayload)\n\n    print(string.format(\"[RoundService] Shift %s concluded! Outcome: %s. Quota: %d/%d\", resultsPayload.ShiftName, isSuccess and \"SURVIVED\" or \"FAILED\", currentQuota, targetQuota))\nend\n\n-- Teardown of round instances\nfunction RoundService:CleanupRound()\n    if services.DisasterService then\n        services.DisasterService:StopActiveDisaster()\n    end\n    if services.TaskService then\n        services.TaskService:ClearAllTasks()\n    end\nend\n\nreturn RoundService\n")
setScript(getOrCreateFolder(game:GetService("ServerScriptService"), "Services"), "TaskService", "ModuleScript", "--!strict\n--[[\n    PANIC SHIFT: TaskService.lua\n    Server-authoritative task manager. Dynamically spawns interactive physical tasks\n    (Restock, Spill, Delivery, Repair) at map anchors with ProximityPrompts,\n    performs atomic completion validation, and distributes rewards.\n]]\n\nlocal Players = game:GetService(\"Players\")\nlocal CollectionService = game:GetService(\"CollectionService\")\nlocal Workspace = game:GetService(\"Workspace\")\n\nlocal Shared = game:GetService(\"ReplicatedStorage\"):WaitForChild(\"PanicShiftShared\")\nlocal Types = require(Shared:WaitForChild(\"Types\"))\nlocal Config = require(Shared:WaitForChild(\"Config\"))\nlocal Constants = require(Shared:WaitForChild(\"Constants\"))\nlocal Utility = require(Shared:WaitForChild(\"Utility\"))\nlocal Network = require(Shared:WaitForChild(\"Network\"))\n\nlocal TaskService = {\n    Name = \"TaskService\",\n}\n\nlocal services: { [string]: any } = {}\nlocal activeTasks: { [string]: Types.TaskData } = {}\nlocal taskInstances: { [string]: Instance } = {}\nlocal rateLimiter: (key: any) -> boolean\nlocal activeTasksFolder: Folder\n\n-- Helper to create visual effects for physical tasks\nlocal function createPhysicalTaskVisual(taskData: Types.TaskData, parentFolder: Folder): Instance?\n    local taskDef = Config.Tasks[taskData.Type]\n    local holdDuration = taskDef and taskDef.InteractionDuration or 1.5\n\n    if taskData.Type == \"CLEAN_SPILL\" then\n        -- Slippery liquid puddle on floor\n        local puddle = Instance.new(\"Part\")\n        puddle.Name = \"Spill_\" .. taskData.Id\n        puddle.Shape = Enum.PartType.Cylinder\n        puddle.Size = Vector3.new(0.2, 7, 7) -- Cylinder height is X axis\n        puddle.CFrame = CFrame.new(taskData.Position + Vector3.new(0, 0.05, 0)) * CFrame.Angles(0, 0, math.rad(90))\n        puddle.Color = Color3.fromRGB(240, 70, 180) -- Toxic neon berry spill\n        puddle.Material = Enum.Material.Glass\n        puddle.Transparency = 0.25\n        puddle.Anchored = true\n        puddle.CanCollide = false\n        puddle.Parent = parentFolder\n\n        -- Sparkle / soap bubbles\n        local particles = Instance.new(\"ParticleEmitter\")\n        particles.Rate = 5\n        particles.Lifetime = NumberRange.new(1, 2)\n        particles.Speed = NumberRange.new(1, 3)\n        particles.Size = NumberSequence.new(0.4, 0.8)\n        particles.Color = ColorSequence.new(Color3.fromRGB(255, 200, 240))\n        particles.Parent = puddle\n\n        -- ProximityPrompt\n        local prompt = Instance.new(\"ProximityPrompt\")\n        prompt.ActionText = \"Mop Spill\"\n        prompt.ObjectText = \"Slippery Mess\"\n        prompt.HoldDuration = holdDuration\n        prompt.MaxActivationDistance = 10\n        prompt.RequiresLineOfSight = false\n        prompt.Parent = puddle\n\n        prompt.Triggered:Connect(function(player: Player)\n            TaskService:HandleTaskAction(player, taskData.Id, \"MOP\")\n        end)\n\n        return puddle\n\n    elseif taskData.Type == \"RESTOCK\" then\n        -- Empty shelf highlight\n        local boxMarker = Instance.new(\"Part\")\n        boxMarker.Name = \"Restock_\" .. taskData.Id\n        boxMarker.Size = Vector3.new(3.5, 2.5, 3.5)\n        boxMarker.CFrame = CFrame.new(taskData.Position)\n        boxMarker.Color = Color3.fromRGB(250, 200, 30)\n        boxMarker.Material = Enum.Material.Neon\n        boxMarker.Transparency = 0.55\n        boxMarker.Anchored = true\n        boxMarker.CanCollide = false\n        boxMarker.Parent = parentFolder\n\n        local prompt = Instance.new(\"ProximityPrompt\")\n        prompt.ActionText = \"Restock Shelf\"\n        prompt.ObjectText = \"Empty Shelf\"\n        prompt.HoldDuration = holdDuration\n        prompt.MaxActivationDistance = 10\n        prompt.RequiresLineOfSight = false\n        prompt.Parent = boxMarker\n\n        prompt.Triggered:Connect(function(player: Player)\n            TaskService:HandleTaskAction(player, taskData.Id, \"RESTOCK\")\n        end)\n\n        return boxMarker\n\n    elseif taskData.Type == \"REPAIR\" then\n        -- Malfunctioning breaker or cooler with electrical sparks\n        local repairMarker = Instance.new(\"Part\")\n        repairMarker.Name = \"Repair_\" .. taskData.Id\n        repairMarker.Size = Vector3.new(2, 2, 2)\n        repairMarker.CFrame = CFrame.new(taskData.Position)\n        repairMarker.Transparency = 1\n        repairMarker.Anchored = true\n        repairMarker.CanCollide = false\n        repairMarker.Parent = parentFolder\n\n        local sparks = Instance.new(\"ParticleEmitter\")\n        sparks.Rate = 18\n        sparks.Speed = NumberRange.new(5, 12)\n        sparks.Lifetime = NumberRange.new(0.2, 0.5)\n        sparks.SpreadAngle = Vector2.new(45, 45)\n        sparks.Color = ColorSequence.new(Color3.fromRGB(255, 230, 80))\n        sparks.Parent = repairMarker\n\n        local prompt = Instance.new(\"ProximityPrompt\")\n        prompt.ActionText = \"Repair Sparks\"\n        prompt.ObjectText = \"Faulty Breaker\"\n        prompt.HoldDuration = holdDuration\n        prompt.MaxActivationDistance = 10\n        prompt.RequiresLineOfSight = false\n        prompt.Parent = repairMarker\n\n        prompt.Triggered:Connect(function(player: Player)\n            TaskService:HandleTaskAction(player, taskData.Id, \"REPAIR\")\n        end)\n\n        return repairMarker\n\n    elseif taskData.Type == \"DELIVER_ORDER\" then\n        -- Delivery order at checkout conveyor\n        local ticketMarker = Instance.new(\"Part\")\n        ticketMarker.Name = \"Order_\" .. taskData.Id\n        ticketMarker.Size = Vector3.new(3, 0.4, 3)\n        ticketMarker.CFrame = CFrame.new(taskData.Position)\n        ticketMarker.Color = Color3.fromRGB(40, 220, 100)\n        ticketMarker.Material = Enum.Material.Neon\n        ticketMarker.Transparency = 0.4\n        ticketMarker.Anchored = true\n        ticketMarker.CanCollide = false\n        ticketMarker.Parent = parentFolder\n\n        local prompt = Instance.new(\"ProximityPrompt\")\n        prompt.ActionText = \"Deliver Groceries\"\n        prompt.ObjectText = \"Customer Order\"\n        prompt.HoldDuration = 1.0\n        prompt.MaxActivationDistance = 10\n        prompt.RequiresLineOfSight = false\n        prompt.Parent = ticketMarker\n\n        prompt.Triggered:Connect(function(player: Player)\n            TaskService:HandleTaskAction(player, taskData.Id, \"DELIVER\")\n        end)\n\n        return ticketMarker\n    end\n\n    return nil\nend\n\nfunction TaskService:Init(serviceRegistry: { [string]: any })\n    services = serviceRegistry\n    rateLimiter = Utility.CreateRateLimiter(Config.RateLimits.TASK_ACTION_MAX_PER_SECOND, 1.0)\n\n    -- Container for spawned task physical instances\n    local existing = Workspace:FindFirstChild(\"ActivePanicShiftTasks\")\n    if existing then\n        existing:Destroy()\n    end\n    activeTasksFolder = Instance.new(\"Folder\")\n    activeTasksFolder.Name = \"ActivePanicShiftTasks\"\n    activeTasksFolder.Parent = Workspace\nend\n\nfunction TaskService:Start()\n    local taskActionFunc = Network.GetRemoteFunction(Constants.Remotes.REQUEST_TASK_ACTION)\n    taskActionFunc.OnServerInvoke = function(player: Player, taskId: any, actionType: any): Types.NetworkResponse\n        return self:HandleTaskAction(player, taskId, actionType)\n    end\nend\n\n-- Populates initial tasks for a shift from the map's anchors\nfunction TaskService:PopulateInitialTasks()\n    self:ClearAllTasks()\n\n    local map = services.RoundService and services.RoundService:GetSupermarketMap()\n    if not map then\n        warn(\"[TaskService] Cannot populate tasks: SupermarketMap not found in Workspace!\")\n        return\n    end\n\n    local taskAnchors = map:FindFirstChild(\"TaskAnchors\")\n    if not taskAnchors then\n        warn(\"[TaskService] TaskAnchors folder not found in SupermarketMap!\")\n        return\n    end\n\n    -- 1. Spills (at least 3 spills)\n    local spillAnchors = {}\n    for _, child in ipairs(taskAnchors:GetChildren()) do\n        if child.Name:find(\"SpillAnchor\") and child:IsA(\"BasePart\") then\n            table.insert(spillAnchors, child)\n        end\n    end\n    for _, anchor in ipairs(spillAnchors) do\n        self:CreateTask(\"CLEAN_SPILL\", anchor.Position, anchor)\n    end\n\n    -- 2. Restocks (shelves needing boxes)\n    local restockAnchors = {}\n    for _, child in ipairs(taskAnchors:GetChildren()) do\n        if child.Name:find(\"RestockTarget\") and child:IsA(\"BasePart\") then\n            table.insert(restockAnchors, child)\n        end\n    end\n    for _, anchor in ipairs(restockAnchors) do\n        self:CreateTask(\"RESTOCK\", anchor.Position, anchor)\n    end\n\n    -- 3. Order Deliveries (checkouts)\n    local orderAnchors = {}\n    for _, child in ipairs(taskAnchors:GetChildren()) do\n        if child.Name:find(\"OrderDropTarget\") and child:IsA(\"BasePart\") then\n            table.insert(orderAnchors, child)\n        end\n    end\n    for idx = 1, math.min(2, #orderAnchors) do\n        local anchor = orderAnchors[idx]\n        self:CreateTask(\"DELIVER_ORDER\", anchor.Position, anchor)\n    end\n\n    -- 4. Repairs (breaker panels)\n    local maintenance = map:FindFirstChild(\"Maintenance\")\n    if maintenance then\n        local b1 = maintenance:FindFirstChild(\"BreakerPanel_1\")\n        if b1 and b1:IsA(\"BasePart\") then\n            self:CreateTask(\"REPAIR\", b1.Position + Vector3.new(1.5, 0, 0), b1)\n        end\n        local cooler = maintenance:FindFirstChild(\"CoolerUnit_2\")\n        if cooler and cooler:IsA(\"BasePart\") then\n            self:CreateTask(\"REPAIR\", cooler.Position + Vector3.new(-2, 0, 0), cooler)\n        end\n    end\n\n    print(string.format(\"[TaskService] Populated %d initial tasks for the shift.\", self:GetActiveTaskCount()))\nend\n\n-- Creates and spawns a single task instance\nfunction TaskService:CreateTask(taskType: Types.TaskType, position: Vector3, locationPart: BasePart?): Types.TaskData\n    local taskId = Utility.GenerateUUID()\n    local taskDef = Config.Tasks[taskType]\n\n    local taskData: Types.TaskData = {\n        Id = taskId,\n        Type = taskType,\n        Title = taskDef and taskDef.Name or \"Supermarket Task\",\n        LocationPart = locationPart,\n        Position = position,\n        IsActive = true,\n        IsCompleted = false,\n        AssignedPlayer = nil,\n        CreatedAt = os.clock(),\n        ExpiresAt = taskDef and taskDef.OrderTimeLimit and (os.clock() + taskDef.OrderTimeLimit) or nil,\n        Metadata = {},\n    }\n\n    activeTasks[taskId] = taskData\n\n    -- Spawn physical 3D interactive object\n    local visualInstance = createPhysicalTaskVisual(taskData, activeTasksFolder)\n    if visualInstance then\n        taskInstances[taskId] = visualInstance\n    end\n\n    -- Broadcast to clients\n    local remote = Network.GetRemoteEvent(Constants.Remotes.TASK_STATE_CHANGED)\n    remote:FireAllClients(taskId, \"CREATED\", {\n        Id = taskData.Id,\n        Type = taskData.Type,\n        Title = taskData.Title,\n        Position = taskData.Position,\n        ExpiresAt = taskData.ExpiresAt,\n    })\n\n    return taskData\nend\n\nfunction TaskService:GetActiveTaskCount(): number\n    local count = 0\n    for _, t in pairs(activeTasks) do\n        if t.IsActive and not t.IsCompleted then\n            count = count + 1\n        end\n    end\n    return count\nend\n\n-- Safely clears all currently active tasks\nfunction TaskService:ClearAllTasks()\n    for taskId, _ in pairs(activeTasks) do\n        local remote = Network.GetRemoteEvent(Constants.Remotes.TASK_STATE_CHANGED)\n        remote:FireAllClients(taskId, \"CLEARED\", nil)\n    end\n\n    for _, inst in pairs(taskInstances) do\n        if inst and inst.Parent then\n            inst:Destroy()\n        end\n    end\n\n    table.clear(activeTasks)\n    table.clear(taskInstances)\nend\n\n-- Validates and processes a player's interaction with a task\nfunction TaskService:HandleTaskAction(player: Player, taskId: any, actionType: any): Types.NetworkResponse\n    -- Anti-exploit: Rate limiting check\n    if not rateLimiter(player.UserId) then\n        return Utility.CreateErrorResponse(Constants.ErrorCodes.RATE_LIMITED, \"Interaction throttled.\")\n    end\n\n    -- Argument validation\n    if typeof(taskId) ~= \"string\" then\n        return Utility.CreateErrorResponse(Constants.ErrorCodes.INVALID_ARGUMENTS, \"Invalid task ID.\")\n    end\n\n    local taskData = activeTasks[taskId]\n    if not taskData then\n        return Utility.CreateErrorResponse(Constants.ErrorCodes.TASK_NOT_FOUND, \"Task does not exist.\")\n    end\n\n    -- Atomic completion lock check (FR-09 / TEST-MP-01)\n    if taskData.IsCompleted then\n        return Utility.CreateErrorResponse(Constants.ErrorCodes.TASK_ALREADY_COMPLETED, \"Task was already completed by another employee.\")\n    end\n\n    if not taskData.IsActive then\n        return Utility.CreateErrorResponse(Constants.ErrorCodes.INVALID_STATE, \"Task is no longer active.\")\n    end\n\n    -- Distance validation (FR-08 / TEST-SEC-02)\n    local charPos = Utility.GetCharacterPosition(player.Character)\n    if not charPos then\n        return Utility.CreateErrorResponse(Constants.ErrorCodes.INVALID_STATE, \"Character position unknown.\")\n    end\n\n    if not Utility.IsWithinDistance(charPos, taskData.Position, Constants.MAX_INTERACTION_DISTANCE) then\n        return Utility.CreateErrorResponse(Constants.ErrorCodes.OUT_OF_RANGE, \"You are too far away from this task.\")\n    end\n\n    -- ATOMIC STATE MUTATION: Mark completed immediately to block race conditions\n    taskData.IsCompleted = true\n    taskData.IsActive = false\n\n    -- Remove physical world instance\n    local visual = taskInstances[taskId]\n    if visual and visual.Parent then\n        visual:Destroy()\n        taskInstances[taskId] = nil\n    end\n\n    local taskDef = Config.Tasks[taskData.Type]\n    local creditReward = taskDef and taskDef.CreditReward or 10\n    local xpReward = taskDef and taskDef.XpReward or 15\n    local quotaPoints = taskDef and taskDef.QuotaPoints or 1\n\n    -- Reward distribution\n    if services.EconomyService then\n        services.EconomyService:AwardCredits(player, creditReward, \"TaskCompletion_\" .. taskData.Type)\n        services.EconomyService:AwardXp(player, xpReward, \"TaskCompletion_\" .. taskData.Type)\n    end\n\n    -- Quota contribution\n    if services.RoundService then\n        services.RoundService:AddQuotaProgress(quotaPoints, player)\n    end\n\n    -- Daily challenge progress\n    if services.ChallengeService then\n        services.ChallengeService:IncrementProgress(player, \"DAILY_TASKS_10\", 1)\n        if taskData.Type == \"CLEAN_SPILL\" then\n            services.ChallengeService:IncrementProgress(player, \"DAILY_CLEAN_SPILLS_5\", 1)\n        end\n    end\n\n    -- Telemetry\n    if services.AnalyticsService then\n        services.AnalyticsService:LogEvent(\"TaskCompleted\", {\n            PlayerId = player.UserId,\n            TaskType = taskData.Type,\n            TaskId = taskId,\n        })\n    end\n\n    -- Broadcast completion to all clients\n    local remote = Network.GetRemoteEvent(Constants.Remotes.TASK_STATE_CHANGED)\n    remote:FireAllClients(taskId, \"COMPLETED\", {\n        CompletedBy = player.Name,\n    })\n\n    print(string.format(\"[TaskService] Player %s completed %s (+%d Credits, +%d XP, +%d Quota)\", player.Name, taskData.Type, creditReward, xpReward, quotaPoints))\n\n    return Utility.CreateSuccessResponse({\n        TaskId = taskId,\n        CreditsAwarded = creditReward,\n        XpAwarded = xpReward,\n        QuotaPoints = quotaPoints,\n    })\nend\n\nreturn TaskService\n")
setScript(getOrCreateFolder(game:GetService("StarterPlayer"):WaitForChild("StarterPlayerScripts"), "Controllers"), "CameraController", "ModuleScript", "--!strict\n--[[\n    PANIC SHIFT: CameraController.lua\n    Manages trauma-based camera shakes, FOV shifts during closing rush,\n    and comedic stumble punch-ins with full accessibility toggle support.\n]]\n\nlocal Workspace = game:GetService(\"Workspace\")\nlocal RunService = game:GetService(\"RunService\")\n\nlocal CameraController = {\n    Name = \"CameraController\",\n}\n\nlocal controllers: { [string]: any } = {}\nlocal camera: Camera? = Workspace.CurrentCamera\n\n-- Camera Shake Parameters\nlocal trauma: number = 0\nlocal TRAUMA_DECAY_RATE: number = 1.8\nlocal MAX_TRANSLATION_STUDS: number = 1.2\nlocal MAX_ROTATION_DEGREES: number = 3.5\n\n-- FOV Parameters\nlocal DEFAULT_FOV: number = 70\nlocal CLOSING_RUSH_FOV: number = 82\nlocal currentFov: number = DEFAULT_FOV\nlocal targetBaseFov: number = DEFAULT_FOV\nlocal fovPunchOffset: number = 0\nlocal FOV_LERP_SPEED: number = 6.0\nlocal PUNCH_DECAY_SPEED: number = 8.0\n\n-- Perlin noise seed\nlocal noiseTime: number = 0\n\nfunction CameraController:Init(controllerRegistry: { [string]: any })\n    controllers = controllerRegistry\nend\n\nfunction CameraController:Start()\n    camera = Workspace.CurrentCamera\n    if camera then\n        currentFov = camera.FieldOfView\n    end\n\n    RunService.RenderStepped:Connect(function(deltaTime: number)\n        if not camera then\n            camera = Workspace.CurrentCamera\n            if not camera then\n                return\n            end\n        end\n\n        local uiCtrl = controllers[\"UIController\"]\n        local isShakeEnabled = true\n        if uiCtrl and typeof(uiCtrl.IsScreenShakeEnabled) == \"function\" then\n            isShakeEnabled = uiCtrl:IsScreenShakeEnabled()\n        end\n\n        -- 1. Trauma decay and shake calculation\n        if trauma > 0 then\n            trauma = math.max(0, trauma - (deltaTime * TRAUMA_DECAY_RATE))\n\n            if isShakeEnabled and trauma > 0.01 then\n                noiseTime = noiseTime + (deltaTime * 35.0)\n                local shakeFactor = trauma * trauma -- Quadratic falloff for physical punch\n\n                local offsetX = (math.noise(noiseTime, 0, 0) or 0) * MAX_TRANSLATION_STUDS * shakeFactor\n                local offsetY = (math.noise(0, noiseTime, 0) or 0) * MAX_TRANSLATION_STUDS * shakeFactor\n                local offsetZ = (math.noise(0, 0, noiseTime) or 0) * (MAX_TRANSLATION_STUDS * 0.5) * shakeFactor\n\n                local rotX = math.rad((math.noise(noiseTime + 10, 0, 0) or 0) * MAX_ROTATION_DEGREES * shakeFactor)\n                local rotY = math.rad((math.noise(0, noiseTime + 10, 0) or 0) * MAX_ROTATION_DEGREES * shakeFactor)\n                local rotZ = math.rad((math.noise(0, 0, noiseTime + 10) or 0) * (MAX_ROTATION_DEGREES * 1.5) * shakeFactor)\n\n                local shakeCFrame = CFrame.new(offsetX, offsetY, offsetZ) * CFrame.Angles(rotX, rotY, rotZ)\n                camera.CFrame = camera.CFrame * shakeCFrame\n            end\n        end\n\n        -- 2. Dynamic FOV Smoothing\n        if math.abs(fovPunchOffset) > 0.1 then\n            fovPunchOffset = fovPunchOffset - (fovPunchOffset * math.clamp(deltaTime * PUNCH_DECAY_SPEED, 0, 1))\n        else\n            fovPunchOffset = 0\n        end\n\n        local desiredFov = targetBaseFov + fovPunchOffset\n        currentFov = currentFov + ((desiredFov - currentFov) * math.clamp(deltaTime * FOV_LERP_SPEED, 0, 1))\n        camera.FieldOfView = currentFov\n    end)\n\n    print(\"[PanicShift CameraController] Camera shake & dynamic FOV active.\")\nend\n\n-- Adds trauma to the camera [0 to 1]\nfunction CameraController:TriggerShake(intensity: number)\n    local clamped = math.clamp(intensity, 0, 1)\n    trauma = math.clamp(trauma + clamped, 0, 1)\nend\n\n-- Sets base FOV (e.g. for Closing Rush wide angle)\nfunction CameraController:SetTargetFov(fov: number)\n    targetBaseFov = math.clamp(fov, 50, 100)\nend\n\n-- Temporarily punches FOV (e.g. quick zoom punch on impact or stumble)\nfunction CameraController:PunchFov(amount: number)\n    fovPunchOffset = math.clamp(fovPunchOffset + amount, -25, 25)\nend\n\nfunction CameraController:SetClosingRushActive(active: boolean)\n    if active then\n        self:SetTargetFov(CLOSING_RUSH_FOV)\n        self:PunchFov(-6) -- Quick punch-in before widening for dramatic flair\n    else\n        self:SetTargetFov(DEFAULT_FOV)\n    end\nend\n\nreturn CameraController\n")
setScript(getOrCreateFolder(game:GetService("StarterPlayer"):WaitForChild("StarterPlayerScripts"), "Controllers"), "EffectsController", "ModuleScript", "--!strict\n--[[\n    PANIC SHIFT: EffectsController.lua\n    Client visual effects, sound dispatch, particle generation,\n    and comedic stumble/slip ragdoll reactions.\n]]\n\nlocal Players = game:GetService(\"Players\")\nlocal TweenService = game:GetService(\"TweenService\")\nlocal SoundService = game:GetService(\"SoundService\")\nlocal Workspace = game:GetService(\"Workspace\")\nlocal Debris = game:GetService(\"Debris\")\n\nlocal Shared = game:GetService(\"ReplicatedStorage\"):WaitForChild(\"PanicShiftShared\")\nlocal Constants = require(Shared:WaitForChild(\"Constants\"))\n\nlocal EffectsController = {\n    Name = \"EffectsController\",\n}\n\nlocal controllers: { [string]: any } = {}\nlocal activeLoops: { [string]: Sound } = {}\nlocal soundFolder: Folder\n\n-- Audio definition registry: primary sound asset with fallback\nexport type SoundDef = {\n    Id: string,\n    FallbackId: string?,\n    Volume: number,\n    Pitch: number,\n    Looped: boolean?,\n}\n\nlocal SOUND_CATALOG: { [string]: SoundDef } = {\n    TaskComplete = {\n        Id = \"rbxasset://sounds/electronicpingshort.wav\",\n        FallbackId = \"rbxassetid://6026947094\",\n        Volume = 0.75,\n        Pitch = 1.1,\n    },\n    CashRegister = {\n        Id = \"rbxasset://sounds/bell.wav\",\n        FallbackId = \"rbxassetid://9069609200\",\n        Volume = 0.85,\n        Pitch = 1.0,\n    },\n    DisasterTelegraph = {\n        Id = \"rbxasset://sounds/action_falling.mp3\",\n        FallbackId = \"rbxassetid://9065458027\",\n        Volume = 0.85,\n        Pitch = 0.95,\n    },\n    DisasterActive = {\n        Id = \"rbxasset://sounds/impact_glass_medium.mp3\",\n        FallbackId = \"rbxassetid://9065365518\",\n        Volume = 0.9,\n        Pitch = 0.9,\n    },\n    DisasterCleared = {\n        Id = \"rbxasset://sounds/action_get_powerup.mp3\",\n        FallbackId = \"rbxassetid://6026947094\",\n        Volume = 0.7,\n        Pitch = 1.25,\n    },\n    SlipStumble = {\n        Id = \"rbxasset://sounds/uuch.wav\",\n        FallbackId = \"rbxassetid://9114223171\",\n        Volume = 0.8,\n        Pitch = 1.15,\n    },\n    CartRattle = {\n        Id = \"rbxasset://sounds/action_footsteps_plastic.mp3\",\n        FallbackId = \"rbxassetid://9114221580\",\n        Volume = 0.5,\n        Pitch = 1.0,\n        Looped = true,\n    },\n    Sparks = {\n        Id = \"rbxasset://sounds/electronicpingshort.wav\",\n        FallbackId = \"rbxassetid://9114223842\",\n        Volume = 0.65,\n        Pitch = 1.3,\n    },\n    ButtonClick = {\n        Id = \"rbxasset://sounds/button.wav\",\n        FallbackId = \"rbxassetid://6895079853\",\n        Volume = 0.45,\n        Pitch = 1.1,\n    },\n    RushSiren = {\n        Id = \"rbxasset://sounds/action_jump.mp3\",\n        FallbackId = \"rbxassetid://9065458027\",\n        Volume = 0.8,\n        Pitch = 1.05,\n    },\n}\n\nfunction EffectsController:Init(controllerRegistry: { [string]: any })\n    controllers = controllerRegistry\n\n    soundFolder = Instance.new(\"Folder\")\n    soundFolder.Name = \"PanicShiftClientAudio\"\n    soundFolder.Parent = SoundService\nend\n\nfunction EffectsController:Start()\n    print(\"[PanicShift EffectsController] Audio, Particle & Animation systems active.\")\nend\n\n-- ====================================================================\n-- AUDIO DISPATCHER\n-- ====================================================================\n\nfunction EffectsController:PlaySound(\n    soundName: string,\n    targetPositionOrPart: (Vector3 | Instance)?,\n    customOptions: { Volume: number?, Pitch: number?, Looped: boolean? }?\n): Sound?\n    local soundDef = SOUND_CATALOG[soundName]\n    if not soundDef then\n        warn(string.format(\"[EffectsController] Unknown sound name: %s\", soundName))\n        return nil\n    end\n\n    local sound = Instance.new(\"Sound\")\n    sound.Name = soundName\n    sound.SoundId = soundDef.Id\n    sound.Volume = if customOptions and customOptions.Volume ~= nil then customOptions.Volume else soundDef.Volume\n    \n    -- Slight natural pitch variation for organic party game feel (±5%)\n    local basePitch = if customOptions and customOptions.Pitch ~= nil then customOptions.Pitch else soundDef.Pitch\n    local pitchVariation = (math.random(95, 105) / 100)\n    sound.PlaybackSpeed = math.clamp(basePitch * pitchVariation, 0.5, 2.0)\n    sound.Looped = if customOptions and customOptions.Looped ~= nil then customOptions.Looped else (soundDef.Looped or false)\n\n    if targetPositionOrPart then\n        if typeof(targetPositionOrPart) == \"Vector3\" then\n            local attachment = Instance.new(\"Attachment\")\n            attachment.WorldPosition = targetPositionOrPart\n            attachment.Parent = Workspace.Terrain\n            sound.Parent = attachment\n            \n            sound.Ended:Connect(function()\n                attachment:Destroy()\n            end)\n        elseif typeof(targetPositionOrPart) == \"Instance\" then\n            sound.Parent = targetPositionOrPart\n        end\n    else\n        sound.Parent = soundFolder\n    end\n\n    sound:Play()\n\n    if not sound.Looped then\n        sound.Ended:Connect(function()\n            sound:Destroy()\n        end)\n        -- Hard cleanup failsafe\n        Debris:AddItem(sound, 8)\n    else\n        activeLoops[soundName] = sound\n    end\n\n    return sound\nend\n\nfunction EffectsController:StopSound(soundName: string)\n    local active = activeLoops[soundName]\n    if active then\n        active:Stop()\n        active:Destroy()\n        activeLoops[soundName] = nil\n    end\nend\n\nfunction EffectsController:PlayButtonClick()\n    self:PlaySound(\"ButtonClick\")\nend\n\nfunction EffectsController:PlayCreditSound()\n    self:PlaySound(\"CashRegister\")\nend\n\nfunction EffectsController:PlayTaskSuccess(taskType: string, position: Vector3?)\n    self:PlaySound(\"TaskComplete\", position)\n    if position then\n        self:EmitTaskSuccess(position)\n    end\nend\n\nfunction EffectsController:PlayDisasterAudio(disasterId: string, status: string)\n    if status == Constants.DisasterStatus.TELEGRAPH then\n        self:PlaySound(\"DisasterTelegraph\")\n    elseif status == Constants.DisasterStatus.ACTIVE then\n        self:PlaySound(\"DisasterActive\")\n        if disasterId == Constants.Disasters.RUNAWAY_CARTS then\n            self:PlaySound(\"CartRattle\", nil, { Looped = true })\n        elseif disasterId == Constants.Disasters.BLACKOUT then\n            self:PlaySound(\"Sparks\")\n        end\n    elseif status == Constants.DisasterStatus.COMPLETED or status == Constants.DisasterStatus.CANCELLED then\n        self:StopSound(\"CartRattle\")\n        self:PlaySound(\"DisasterCleared\")\n    end\nend\n\n-- ====================================================================\n-- PROCEDURAL PARTICLES\n-- ====================================================================\n\n-- Bursts celebratory stars / sparkles at completed task location\nfunction EffectsController:EmitTaskSuccess(worldPosition: Vector3)\n    local attachment = Instance.new(\"Attachment\")\n    attachment.WorldPosition = worldPosition + Vector3.new(0, 1.5, 0)\n    attachment.Parent = Workspace.Terrain\n\n    local emitter = Instance.new(\"ParticleEmitter\")\n    emitter.Name = \"TaskSuccessSparkles\"\n    emitter.Texture = \"rbxasset://textures/particles/sparkles_main.dds\"\n    emitter.Color = ColorSequence.new({\n        ColorSequenceKeypoint.new(0, Color3.fromRGB(255, 230, 80)),\n        ColorSequenceKeypoint.new(0.5, Color3.fromRGB(50, 255, 150)),\n        ColorSequenceKeypoint.new(1, Color3.fromRGB(255, 255, 255)),\n    })\n    emitter.Size = NumberSequence.new({\n        NumberSequenceKeypoint.new(0, 0.4),\n        NumberSequenceKeypoint.new(0.5, 1.2),\n        NumberSequenceKeypoint.new(1, 0),\n    })\n    emitter.Transparency = NumberSequence.new({\n        NumberSequenceKeypoint.new(0, 0),\n        NumberSequenceKeypoint.new(0.8, 0.2),\n        NumberSequenceKeypoint.new(1, 1),\n    })\n    emitter.Speed = NumberRange.new(4, 9)\n    emitter.SpreadAngle = Vector2.new(180, 180)\n    emitter.Lifetime = NumberRange.new(0.6, 1.2)\n    emitter.Rate = 0\n    emitter.LightEmission = 0.8\n    emitter.Parent = attachment\n\n    emitter:Emit(25)\n    Debris:AddItem(attachment, 1.5)\nend\n\n-- Attaches gentle bubbles to spill areas\nfunction EffectsController:CreateSpillBubbles(parentPart: BasePart): ParticleEmitter\n    local emitter = Instance.new(\"ParticleEmitter\")\n    emitter.Name = \"SpillBubbles\"\n    emitter.Texture = \"rbxasset://textures/particles/sparkles_main.dds\"\n    emitter.Color = ColorSequence.new(Color3.fromRGB(130, 225, 255), Color3.fromRGB(80, 190, 240))\n    emitter.Size = NumberSequence.new(0.3, 0.8)\n    emitter.Transparency = NumberSequence.new(0.2, 0.8)\n    emitter.Lifetime = NumberRange.new(1.0, 2.0)\n    emitter.Speed = NumberRange.new(1.5, 3.5)\n    emitter.Rate = 8\n    emitter.Acceleration = Vector3.new(0, 2, 0)\n    emitter.Parent = parentPart\n    return emitter\nend\n\n-- Attaches electrical spark bursts to breaker and maintenance panels\nfunction EffectsController:CreateBreakerSparks(parentPart: BasePart): ParticleEmitter\n    local emitter = Instance.new(\"ParticleEmitter\")\n    emitter.Name = \"BreakerSparks\"\n    emitter.Texture = \"rbxasset://textures/particles/sparkles_main.dds\"\n    emitter.Color = ColorSequence.new(Color3.fromRGB(255, 240, 120), Color3.fromRGB(255, 140, 20))\n    emitter.Size = NumberSequence.new(0.2, 0.6)\n    emitter.Speed = NumberRange.new(6, 14)\n    emitter.SpreadAngle = Vector2.new(60, 60)\n    emitter.Lifetime = NumberRange.new(0.2, 0.5)\n    emitter.Rate = 12\n    emitter.Acceleration = Vector3.new(0, -20, 0)\n    emitter.LightEmission = 1.0\n    emitter.Parent = parentPart\n    return emitter\nend\n\n-- Attaches slippery foam particles for soap disaster\nfunction EffectsController:CreateSoapFoam(parentPart: BasePart): ParticleEmitter\n    local emitter = Instance.new(\"ParticleEmitter\")\n    emitter.Name = \"SoapFoam\"\n    emitter.Texture = \"rbxasset://textures/particles/smoke_main.dds\"\n    emitter.Color = ColorSequence.new(Color3.fromRGB(240, 250, 255))\n    emitter.Size = NumberSequence.new(0.6, 1.4)\n    emitter.Transparency = NumberSequence.new(0.3, 0.9)\n    emitter.Lifetime = NumberRange.new(1.0, 1.8)\n    emitter.Speed = NumberRange.new(0.5, 1.5)\n    emitter.Rate = 10\n    emitter.SpreadAngle = Vector2.new(180, 180)\n    emitter.Parent = parentPart\n    return emitter\nend\n\n-- Attaches dust cloud puff for avalanche collapses\nfunction EffectsController:CreateAvalancheDust(parentPart: BasePart): ParticleEmitter\n    local emitter = Instance.new(\"ParticleEmitter\")\n    emitter.Name = \"AvalancheDust\"\n    emitter.Texture = \"rbxasset://textures/particles/smoke_main.dds\"\n    emitter.Color = ColorSequence.new(Color3.fromRGB(190, 175, 160))\n    emitter.Size = NumberSequence.new(1.5, 4.0)\n    emitter.Transparency = NumberSequence.new(0.2, 1.0)\n    emitter.Lifetime = NumberRange.new(1.2, 2.4)\n    emitter.Speed = NumberRange.new(4, 10)\n    emitter.SpreadAngle = Vector2.new(180, 180)\n    emitter.Rate = 20\n    emitter.Parent = parentPart\n    return emitter\nend\n\n-- ====================================================================\n-- PROCEDURAL CHARACTER STUMBLES / PHYSICAL COMEDY (FR-12)\n-- ====================================================================\n\n-- Plays a temporary stumble/slip ragdoll reaction\nfunction EffectsController:PlayStumbleReaction(duration: number, knockbackVelocity: Vector3?)\n    local localPlayer = Players.LocalPlayer\n    local character = localPlayer.Character\n    if not character then\n        return\n    end\n\n    local humanoid = character:FindFirstChildOfClass(\"Humanoid\")\n    local rootPart = character:FindFirstChild(\"HumanoidRootPart\") :: BasePart?\n    if not humanoid or not rootPart then\n        return\n    end\n\n    -- Trigger stumble sound & camera shock\n    self:PlaySound(\"SlipStumble\", rootPart.Position)\n    local cameraCtrl = controllers[\"CameraController\"]\n    if cameraCtrl and typeof(cameraCtrl.TriggerShake) == \"function\" then\n        cameraCtrl:TriggerShake(0.75)\n    end\n\n    -- Apply comedic knockback impulse\n    if knockbackVelocity then\n        rootPart.AssemblyLinearVelocity = knockbackVelocity\n    else\n        local randomImpulse = Vector3.new(\n            math.random(-25, 25),\n            math.random(15, 30),\n            math.random(-25, 25)\n        )\n        rootPart.AssemblyLinearVelocity = randomImpulse\n    end\n\n    -- Ragdoll stumble state\n    humanoid.PlatformStand = true\n\n    local safeDuration = math.clamp(duration, 0.4, 2.5)\n    task.delay(safeDuration, function()\n        if humanoid and humanoid.Parent then\n            humanoid.PlatformStand = false\n            humanoid:ChangeState(Enum.HumanoidStateType.GettingUp)\n        end\n    end)\nend\n\nreturn EffectsController\n")
setScript(getOrCreateFolder(game:GetService("StarterPlayer"):WaitForChild("StarterPlayerScripts"), "Controllers"), "InputController", "ModuleScript", "--!strict\n--[[\n    PANIC SHIFT: InputController.lua\n    Unified cross-platform input manager (Keyboard, Touch, Gamepad).\n    Handles action bindings for Interact, Sprint, Emote, Shop Toggle,\n    and Gamepad B/Keyboard Escape modal dismissal.\n]]\n\nlocal ContextActionService = game:GetService(\"ContextActionService\")\nlocal UserInputService = game:GetService(\"UserInputService\")\nlocal Players = game:GetService(\"Players\")\n\nlocal InputController = {\n    Name = \"InputController\",\n}\n\nlocal controllers: { [string]: any } = {}\n\nlocal ACTION_INTERACT = \"PanicShift_Interact\"\nlocal ACTION_SPRINT = \"PanicShift_Sprint\"\nlocal ACTION_TOGGLE_SHOP = \"PanicShift_ToggleShop\"\nlocal ACTION_CLOSE_MODAL = \"PanicShift_CloseModal\"\n\nfunction InputController:Init(controllerRegistry: { [string]: any })\n    controllers = controllerRegistry\nend\n\nfunction InputController:Start()\n    print(\"[PanicShift InputController] Binding cross-platform actions (PC, Touch, Gamepad)...\")\n\n    -- 1. Bind Interact (E / ButtonX / Mobile Touch Button)\n    ContextActionService:BindAction(\n        ACTION_INTERACT,\n        function(actionName, inputState, inputObject)\n            if inputState == Enum.UserInputState.Begin then\n                if controllers.InteractionController then\n                    controllers.InteractionController:TriggerCurrentInteraction()\n                end\n            end\n            return Enum.ContextActionResult.Pass\n        end,\n        true, -- Generates mobile touch button\n        Enum.KeyCode.E,\n        Enum.KeyCode.ButtonX\n    )\n    ContextActionService:SetTitle(ACTION_INTERACT, \"Interact\")\n    ContextActionService:SetPosition(ACTION_INTERACT, UDim2.new(1, -120, 1, -140))\n\n    -- 2. Bind Sprint (LeftShift / Gamepad L3)\n    ContextActionService:BindAction(\n        ACTION_SPRINT,\n        function(actionName, inputState, inputObject)\n            local character = Players.LocalPlayer.Character\n            local humanoid = character and character:FindFirstChildOfClass(\"Humanoid\")\n            if humanoid then\n                if inputState == Enum.UserInputState.Begin then\n                    humanoid.WalkSpeed = 24 -- Sprint speed\n                elseif inputState == Enum.UserInputState.End then\n                    humanoid.WalkSpeed = 16 -- Normal speed\n                end\n            end\n            return Enum.ContextActionResult.Pass\n        end,\n        false,\n        Enum.KeyCode.LeftShift,\n        Enum.KeyCode.ButtonL3\n    )\n\n    -- 3. Bind Toggle Shop (M / Gamepad ButtonY)\n    ContextActionService:BindAction(\n        ACTION_TOGGLE_SHOP,\n        function(actionName, inputState, inputObject)\n            if inputState == Enum.UserInputState.Begin then\n                local uiCtrl = controllers.UIController\n                if uiCtrl and uiCtrl.ToggleShop then\n                    uiCtrl:ToggleShop()\n                end\n            end\n            return Enum.ContextActionResult.Pass\n        end,\n        false,\n        Enum.KeyCode.M,\n        Enum.KeyCode.ButtonY\n    )\n\n    -- 4. Bind Modal Dismissal (Escape / Gamepad ButtonB)\n    ContextActionService:BindAction(\n        ACTION_CLOSE_MODAL,\n        function(actionName, inputState, inputObject)\n            if inputState == Enum.UserInputState.Begin then\n                local playerGui = Players.LocalPlayer:FindFirstChild(\"PlayerGui\")\n                local gui = playerGui and playerGui:FindFirstChild(\"PanicShiftGui\")\n                if gui then\n                    local shop = gui:FindFirstChild(\"ShopModal\")\n                    if shop and shop.Visible then shop.Visible = false return Enum.ContextActionResult.Sink end\n                    local ch = gui:FindFirstChild(\"ChallengesModal\")\n                    if ch and ch.Visible then ch.Visible = false return Enum.ContextActionResult.Sink end\n                    local st = gui:FindFirstChild(\"SettingsModal\")\n                    if st and st.Visible then st.Visible = false return Enum.ContextActionResult.Sink end\n                    local res = gui:FindFirstChild(\"ResultsModal\")\n                    if res and res.Visible then res.Visible = false return Enum.ContextActionResult.Sink end\n                end\n            end\n            return Enum.ContextActionResult.Pass\n        end,\n        false,\n        Enum.KeyCode.Escape,\n        Enum.KeyCode.ButtonB\n    )\nend\n\nfunction InputController:IsTouchDevice(): boolean\n    return UserInputService.TouchEnabled and not UserInputService.KeyboardEnabled\nend\n\nfunction InputController:IsGamepadConnected(): boolean\n    return UserInputService.GamepadEnabled\nend\n\nreturn InputController\n")
setScript(getOrCreateFolder(game:GetService("StarterPlayer"):WaitForChild("StarterPlayerScripts"), "Controllers"), "InteractionController", "ModuleScript", "--!strict\n--[[\n    PANIC SHIFT: InteractionController.lua\n    Client raycasting, prompt detection, task interaction dispatcher,\n    and audiovisual feedback trigger.\n]]\n\nlocal Players = game:GetService(\"Players\")\n\nlocal Shared = game:GetService(\"ReplicatedStorage\"):WaitForChild(\"PanicShiftShared\")\nlocal Types = require(Shared:WaitForChild(\"Types\"))\nlocal Constants = require(Shared:WaitForChild(\"Constants\"))\nlocal Network = require(Shared:WaitForChild(\"Network\"))\n\nlocal InteractionController = {\n    Name = \"InteractionController\",\n}\n\nlocal controllers: { [string]: any } = {}\nlocal currentFocusedTaskId: string? = nil\nlocal knownClientTasks: { [string]: any } = {}\n\nfunction InteractionController:Init(controllerRegistry: { [string]: any })\n    controllers = controllerRegistry\nend\n\nfunction InteractionController:Start()\n    local taskStateRemote = Network.GetRemoteEvent(Constants.Remotes.TASK_STATE_CHANGED)\n    taskStateRemote.OnClientEvent:Connect(function(taskId: string, eventType: string, data: any)\n        if eventType == \"CREATED\" then\n            knownClientTasks[taskId] = data\n        elseif eventType == \"COMPLETED\" or eventType == \"CLEARED\" then\n            knownClientTasks[taskId] = nil\n            if currentFocusedTaskId == taskId then\n                currentFocusedTaskId = nil\n            end\n        end\n    end)\nend\n\nfunction InteractionController:SetFocusedTask(taskId: string?)\n    currentFocusedTaskId = taskId\nend\n\nfunction InteractionController:TriggerCurrentInteraction(): ()\n    if not currentFocusedTaskId then\n        return\n    end\n\n    local taskId = currentFocusedTaskId\n    local taskInfo = knownClientTasks[taskId]\n    local requestFunc = Network.GetRemoteFunction(Constants.Remotes.REQUEST_TASK_ACTION)\n    local response: Types.NetworkResponse = requestFunc:InvokeServer(taskId, \"INTERACT\")\n\n    if response.Success then\n        print(string.format(\"[Interaction] Completed task %s successfully!\", taskId))\n        currentFocusedTaskId = nil\n\n        -- Milestone 8: Trigger positive task completion effects\n        local effectsCtrl = controllers[\"EffectsController\"]\n        local cameraCtrl = controllers[\"CameraController\"]\n\n        local taskType = if taskInfo and taskInfo.Type then taskInfo.Type else \"RESTOCK\"\n        local worldPos: Vector3? = nil\n\n        local character = Players.LocalPlayer.Character\n        if character and character:FindFirstChild(\"HumanoidRootPart\") then\n            worldPos = (character:FindFirstChild(\"HumanoidRootPart\") :: BasePart).Position\n        end\n\n        if effectsCtrl and typeof(effectsCtrl.PlayTaskSuccess) == \"function\" then\n            effectsCtrl:PlayTaskSuccess(taskType, worldPos)\n        end\n\n        if cameraCtrl then\n            if typeof(cameraCtrl.TriggerShake) == \"function\" then\n                cameraCtrl:TriggerShake(0.15)\n            end\n            if typeof(cameraCtrl.PunchFov) == \"function\" then\n                cameraCtrl:PunchFov(2.0)\n            end\n        end\n    else\n        warn(string.format(\"[Interaction] Task rejected: %s (%s)\", response.Message or \"\", response.ErrorCode))\n    end\nend\n\nreturn InteractionController\n")
setScript(getOrCreateFolder(game:GetService("StarterPlayer"):WaitForChild("StarterPlayerScripts"), "Controllers"), "UIBuilder", "ModuleScript", "--!strict\n--[[\n    PANIC SHIFT: UIBuilder.lua\n    Procedural UI builder creating the complete responsive ScreenGui hierarchy.\n    Includes Shift HUD, Disaster Alert Banners, Results Modal, Cosmetic Shop,\n    Daily Challenges Drawer, and Settings.\n]]\n\nlocal Players = game:GetService(\"Players\")\n\nlocal UIBuilder = {}\n\nlocal COLORS = {\n    BRAND_GREEN = Color3.fromRGB(26, 120, 68),\n    BRAND_ORANGE = Color3.fromRGB(235, 95, 20),\n    BRAND_YELLOW = Color3.fromRGB(250, 200, 30),\n    DARK_BG = Color3.fromRGB(22, 25, 34),\n    CARD_BG = Color3.fromRGB(32, 36, 48),\n    CARD_HOVER = Color3.fromRGB(44, 50, 66),\n    WHITE = Color3.fromRGB(255, 255, 255),\n    GRAY_TEXT = Color3.fromRGB(180, 185, 200),\n    DANGER_RED = Color3.fromRGB(235, 50, 50),\n    SUCCESS_GREEN = Color3.fromRGB(40, 200, 90),\n}\n\nlocal FONT_BOLD = Enum.Font.FredokaOne\nlocal FONT_REGULAR = Enum.Font.GothamMedium\n\nlocal function createCorner(parent: Instance, radius: number): UICorner\n    local corner = Instance.new(\"UICorner\")\n    corner.CornerRadius = UDim.new(0, radius)\n    corner.Parent = parent\n    return corner\nend\n\nlocal function createStroke(parent: Instance, color: Color3, thickness: number): UIStroke\n    local stroke = Instance.new(\"UIStroke\")\n    stroke.Color = color\n    stroke.Thickness = thickness\n    stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border\n    stroke.Parent = parent\n    return stroke\nend\n\nfunction UIBuilder.Build(playerGui: PlayerGui): { [string]: any }\n    -- Clear any old GUI\n    local existing = playerGui:FindFirstChild(\"PanicShiftGui\")\n    if existing then\n        existing:Destroy()\n    end\n\n    local screenGui = Instance.new(\"ScreenGui\")\n    screenGui.Name = \"PanicShiftGui\"\n    screenGui.ResetOnSpawn = false\n    screenGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling\n    screenGui.Parent = playerGui\n\n    local refs: { [string]: any } = {\n        ScreenGui = screenGui,\n    }\n\n    -- =========================================================================\n    -- 1. TOP CENTER: SHIFT HUD (Timer & Quota Progress)\n    -- =========================================================================\n    local topCenterFrame = Instance.new(\"Frame\")\n    topCenterFrame.Name = \"TopCenter_ShiftHeader\"\n    topCenterFrame.Size = UDim2.new(0, 340, 0, 84)\n    topCenterFrame.Position = UDim2.new(0.5, -170, 0, 16)\n    topCenterFrame.BackgroundColor3 = COLORS.DARK_BG\n    topCenterFrame.BackgroundTransparency = 0.15\n    topCenterFrame.BorderSizePixel = 0\n    topCenterFrame.Parent = screenGui\n    createCorner(topCenterFrame, 14)\n    createStroke(topCenterFrame, Color3.fromRGB(50, 55, 75), 1.5)\n\n    local shiftTimerLabel = Instance.new(\"TextLabel\")\n    shiftTimerLabel.Name = \"ShiftTimerLabel\"\n    shiftTimerLabel.Size = UDim2.new(0, 100, 0, 34)\n    shiftTimerLabel.Position = UDim2.new(0, 12, 0, 6)\n    shiftTimerLabel.BackgroundTransparency = 1\n    shiftTimerLabel.Text = \"03:00\"\n    shiftTimerLabel.TextColor3 = COLORS.WHITE\n    shiftTimerLabel.Font = FONT_BOLD\n    shiftTimerLabel.TextSize = 28\n    shiftTimerLabel.TextXAlignment = Enum.TextXAlignment.Left\n    shiftTimerLabel.Parent = topCenterFrame\n    refs.ShiftTimerLabel = shiftTimerLabel\n\n    local shiftStateBadge = Instance.new(\"TextLabel\")\n    shiftStateBadge.Name = \"ShiftStateBadge\"\n    shiftStateBadge.Size = UDim2.new(0, 200, 0, 24)\n    shiftStateBadge.Position = UDim2.new(1, -212, 0, 10)\n    shiftStateBadge.BackgroundColor3 = COLORS.BRAND_GREEN\n    shiftStateBadge.Text = \"ACTIVE SHIFT\"\n    shiftStateBadge.TextColor3 = COLORS.WHITE\n    shiftStateBadge.Font = FONT_BOLD\n    shiftStateBadge.TextSize = 13\n    shiftStateBadge.Parent = topCenterFrame\n    createCorner(shiftStateBadge, 6)\n    refs.ShiftStateBadge = shiftStateBadge\n\n    -- Quota Bar Container\n    local quotaContainer = Instance.new(\"Frame\")\n    quotaContainer.Name = \"QuotaContainer\"\n    quotaContainer.Size = UDim2.new(1, -24, 0, 28)\n    quotaContainer.Position = UDim2.new(0, 12, 1, -38)\n    quotaContainer.BackgroundTransparency = 1\n    quotaContainer.Parent = topCenterFrame\n\n    local quotaBarBg = Instance.new(\"Frame\")\n    quotaBarBg.Name = \"QuotaBarBg\"\n    quotaBarBg.Size = UDim2.new(1, 0, 1, 0)\n    quotaBarBg.BackgroundColor3 = Color3.fromRGB(35, 40, 55)\n    quotaBarBg.BorderSizePixel = 0\n    quotaBarBg.Parent = quotaContainer\n    createCorner(quotaBarBg, 8)\n\n    local quotaBarFill = Instance.new(\"Frame\")\n    quotaBarFill.Name = \"QuotaBarFill\"\n    quotaBarFill.Size = UDim2.new(0.4, 0, 1, 0)\n    quotaBarFill.BackgroundColor3 = COLORS.BRAND_ORANGE\n    quotaBarFill.BorderSizePixel = 0\n    quotaBarFill.Parent = quotaBarBg\n    createCorner(quotaBarFill, 8)\n    refs.QuotaBarFill = quotaBarFill\n\n    local quotaLabel = Instance.new(\"TextLabel\")\n    quotaLabel.Name = \"QuotaLabel\"\n    quotaLabel.Size = UDim2.new(1, 0, 1, 0)\n    quotaLabel.BackgroundTransparency = 1\n    quotaLabel.Text = \"STORE QUOTA: 10 / 25\"\n    quotaLabel.TextColor3 = COLORS.WHITE\n    quotaLabel.Font = FONT_BOLD\n    quotaLabel.TextSize = 14\n    quotaLabel.ZIndex = 3\n    quotaLabel.Parent = quotaContainer\n    refs.QuotaLabel = quotaLabel\n\n    -- =========================================================================\n    -- 2. TOP RIGHT: PLAYER WALLET & XP\n    -- =========================================================================\n    local walletFrame = Instance.new(\"Frame\")\n    walletFrame.Name = \"TopRight_PlayerWallet\"\n    walletFrame.Size = UDim2.new(0, 220, 0, 68)\n    walletFrame.Position = UDim2.new(1, -236, 0, 16)\n    walletFrame.BackgroundColor3 = COLORS.DARK_BG\n    walletFrame.BackgroundTransparency = 0.15\n    walletFrame.BorderSizePixel = 0\n    walletFrame.Parent = screenGui\n    createCorner(walletFrame, 12)\n    createStroke(walletFrame, Color3.fromRGB(50, 55, 75), 1.5)\n\n    local creditLabel = Instance.new(\"TextLabel\")\n    creditLabel.Name = \"CreditLabel\"\n    creditLabel.Size = UDim2.new(1, -70, 0, 28)\n    creditLabel.Position = UDim2.new(0, 14, 0, 8)\n    creditLabel.BackgroundTransparency = 1\n    creditLabel.Text = \"💰 0 CREDITS\"\n    creditLabel.TextColor3 = COLORS.BRAND_YELLOW\n    creditLabel.Font = FONT_BOLD\n    creditLabel.TextSize = 16\n    creditLabel.TextXAlignment = Enum.TextXAlignment.Left\n    creditLabel.Parent = walletFrame\n    refs.CreditLabel = creditLabel\n\n    local levelBadge = Instance.new(\"TextLabel\")\n    levelBadge.Name = \"LevelBadge\"\n    levelBadge.Size = UDim2.new(0, 48, 0, 26)\n    levelBadge.Position = UDim2.new(1, -58, 0, 8)\n    levelBadge.BackgroundColor3 = COLORS.BRAND_ORANGE\n    levelBadge.Text = \"LVL 1\"\n    levelBadge.TextColor3 = COLORS.WHITE\n    levelBadge.Font = FONT_BOLD\n    levelBadge.TextSize = 13\n    levelBadge.Parent = walletFrame\n    createCorner(levelBadge, 6)\n    refs.LevelBadge = levelBadge\n\n    local xpBarBg = Instance.new(\"Frame\")\n    xpBarBg.Name = \"XpBarBg\"\n    xpBarBg.Size = UDim2.new(1, -28, 0, 12)\n    xpBarBg.Position = UDim2.new(0, 14, 1, -22)\n    xpBarBg.BackgroundColor3 = Color3.fromRGB(35, 40, 55)\n    xpBarBg.BorderSizePixel = 0\n    xpBarBg.Parent = walletFrame\n    createCorner(xpBarBg, 6)\n\n    local xpBarFill = Instance.new(\"Frame\")\n    xpBarFill.Name = \"XpBarFill\"\n    xpBarFill.Size = UDim2.new(0.2, 0, 1, 0)\n    xpBarFill.BackgroundColor3 = Color3.fromRGB(60, 160, 255)\n    xpBarFill.BorderSizePixel = 0\n    xpBarFill.Parent = xpBarBg\n    createCorner(xpBarFill, 6)\n    refs.XpBarFill = xpBarFill\n\n    -- =========================================================================\n    -- 3. BOTTOM LEFT: ACTION DRAWER (Shop, Challenges, Settings)\n    -- =========================================================================\n    local drawerFrame = Instan